        self,
        quest_id,
        run_id,
        reason,
        roles,
        limits,
        *,
        strategy,
        expected_version,
        source_event_id=None,
        source_event_token=None,
    ):
        """Request a separately approved, bounded replacement; no budget is refunded."""
