                            "state": "succeeded",
                            "receipt_id": "receipt_" + "0" * 32,
                            "intent_id": "intent_" + "0" * 32,
                            "output": output,
                        }
                    ),
                },
            ]
        )
        growth += 2 * body_bound + 1024
        stages.append(
            {
                "after_tool": name,
                "extra_messages": list(history),
                "future_body_and_receipt_growth": growth,
            }
        )
    return stages

