"""Explicit V23 lossless verifier wire; V21 remains unchanged."""

from typing import Annotated, Literal

from pydantic import Field, model_validator

from .graph_domain import OutputCapacityBounds
from .planner_dataflow import DataflowGraphWire, DataflowNodeWire, DataflowVerifierWire

ARTIFACT_KINDS = ("json_review", "json_valid", "semantic_numeric:scheduler-v1")
INLINE_KINDS = ("delivery_review", "json_review:@delivery")
CanonicalArtifactKind = Annotated[
    str,
    Field(
        min_length=1,
        max_length=2100,
        pattern=r"^(?:json_review|json_valid|semantic_numeric:scheduler-v1):[^\r\n]+$",
    ),
]


class DataflowVerifierWireV23(DataflowVerifierWire):
    kind: (
        Literal[
            "delivery_review",
            "json_review:@delivery",
            "json_review",
            "json_valid",
            "semantic_numeric:scheduler-v1",
        ]
        | CanonicalArtifactKind
    )

    def criterion(self, expected_artifact):
        if self.kind in INLINE_KINDS or self.kind in ARTIFACT_KINDS:
            return super().criterion(expected_artifact)
        if expected_artifact is None:
            raise ValueError("canonical_artifact_verifier_requires_expected_artifact")
        # Exact equality is the entire decoder. No path cleanup, substring,
        # prefix stripping, case folding, default verifier or kind fallback.
        matches = [
            prefix for prefix in ARTIFACT_KINDS if self.kind == prefix + ":" + expected_artifact
        ]
        if len(matches) != 1:
            raise ValueError("canonical_artifact_verifier_path_must_equal_expected_artifact")
        return self.kind


class OutputCapacityBoundsV23(OutputCapacityBounds):
    action_evidence_allowance_bytes: int = Field(
        ge=0,
        le=32768,
        description="Contribution to total source-receipt sizing for planned node action evidence; not an independent cap, authority or executed evidence. Read-only may choose 0.",
    )


class DataflowNodeWireV23(DataflowNodeWire):
    success_criteria: list[DataflowVerifierWireV23] = Field(min_length=1, max_length=5)
    capacity_bounds: OutputCapacityBoundsV23

    @model_validator(mode="after")
    def exact_verifier_encoding(self):
        compiled = [item.criterion(self.expected_artifact) for item in self.success_criteria]
        if len(compiled) != len(set(compiled)):
            raise ValueError("duplicate_semantic_verifier_selection")
        artifact = [item.kind for item in self.success_criteria if item.kind not in INLINE_KINDS]
        if any(item in ARTIFACT_KINDS for item in artifact) and any(
            item not in ARTIFACT_KINDS for item in artifact
        ):
            raise ValueError("mixed_artifact_verifier_encodings")
        return self


class DataflowGraphWireV23(DataflowGraphWire):
    nodes: list[DataflowNodeWireV23] = Field(min_length=1, max_length=8)

    def proposal_data(self, **kwargs):
        result = super().proposal_data(**kwargs)
        pending = {item.key for item in self.nodes}
        allowances = {
            node["key"]: node["capacity_bounds"].pop("action_evidence_allowance_bytes")
            for node in result["nodes"]
            if node["key"] in pending
        }
        result["capacity_contract"] = {
            "input_acquisition_policy": "core-declared-source-prefetch-v1",
            "action_evidence_allowances": allowances,
        }
        return result

"""Read-only complete capacity diagnostics for independently valid V23 nodes."""

import copy
import json

from pydantic import ConfigDict, ValidationError, create_model, model_validator

from .budget_policy import SERIAL_CAPACITY_VERSION, validate_serial_policy
from .capacity_preflight import VERSION, node_review_envelope, verify_input_inventory
from .domain import DomainError
from .planner_dataflow import compile_source_dataflow, validate_source_tools
from .planner_dataflow_v23 import DataflowNodeWireV23
from .planner_resource_policy import PLANNED_WORKER_OUTPUT_TOKENS
from .planner_source_preview import MAX_RESPONSE_BYTES
from .source_capacity import SOURCE_METADATA_RESERVE_BYTES, measure_required_sources
from .team_composition import (
    DEFAULT_OUTPUT_SCHEMA,
    CompositionLimits,
    RoleSpec,
    TeamComposerEngine,
)

MAX_REPORT_BYTES = 8192
NodeWithoutCriteria = create_model(
    "NodeWithoutCriteria",
    __config__=ConfigDict(extra="forbid", strict=True),
    __validators__={"source_tools": model_validator(mode="after")(validate_source_tools)},
    **{
        name: (field.annotation, copy.deepcopy(field))
        for name, field in DataflowNodeWireV23.model_fields.items()
        if name != "success_criteria"
    },
)
NUMBERS = frozenset(
    {
        "known_source_bytes",
        "future_source_bytes_bound",
        "raw_packet_bytes",
        "growth_bound",
        "raw_packet_bound",
        "raw_packet_limit",
        "review_input_bound",
        "correction_input_bound",
        "worker_input_bound",
        "model_context_limit",
        "output_bound",
        "allocated_tokens",
        "native_envelope_fixed_point_iterations",
        "input_acquisition_input_bound",
        "input_acquisition_total_bound",
        "initial_work_tokens",
        "action_completion_calls",
        "action_completion_total_bound",
    }
)


def _unavailable(reason):
    return {
        "version": "planner-capacity-preview-v23",
        "status": "unavailable",
        "reason": reason,
    }


def _preview_complete_capacity(
    service,
    quest,
    raw_response,
    inventory,
    provider,
    *,
    resource_limits,
    coordination_reserve_tokens,
    completed_nodes=(),
    completed_edges=(),
    parent_graph=None,
):
    """Never compiles a partial plan or assigns a replacement criterion.

    The global dataflow projection has no success_criteria for invalid nodes.
    Only a node passing its entire real V23 semantic wire is passed to the
    original pure measurement function. Other nodes remain explicit unknowns.
    No measured graph, resource allocation, plan, tool result or authority exits.
    """
    if not isinstance(raw_response, str) or len(raw_response.encode()) > MAX_RESPONSE_BYTES:
        return _unavailable("response_outside_projection_bound")
    try:
        raw = json.loads(raw_response)
        if not isinstance(raw, dict) or set(raw) != {"allocation_mode", "nodes"}:
            return _unavailable("invalid_projection_root")
        if raw["allocation_mode"] != "core_measured" or not isinstance(raw["nodes"], list):
            return _unavailable("invalid_projection_root")
        if not 1 <= len(raw["nodes"]) <= 8:
            return _unavailable("invalid_projection_nodes")
        projected = [
            NodeWithoutCriteria.model_validate(
                {k: v for k, v in node.items() if k != "success_criteria"}
            )
            for node in raw["nodes"]
        ]
        selected = compile_source_dataflow(
            projected,
            verified_paths=[item["path"] for item in inventory],
            completed_nodes=completed_nodes,
            completed_edges=completed_edges,
        )
        verify_input_inventory(service.store, inventory)
    except (
        KeyError,
        TypeError,
        ValueError,
        RecursionError,
        ValidationError,
        DomainError,
    ):
        return _unavailable("invalid_noncriterion_projection")
    completed = {node["key"] for node in completed_nodes}
    selected_by_key = {node["key"]: node for node in selected["nodes"]}
    valid, nodes, statuses, allowances = {}, [], {}, {}
    for raw_node, projection in zip(raw["nodes"], projected, strict=True):
        node = {
            **projection.model_dump(exclude={"verified_input_paths", "predecessors"}),
            **selected_by_key[projection.key],
            "budget_tokens": 2049,
        }
        capabilities = node["required_capabilities"]
        allowances[node["key"]] = node["capacity_bounds"].pop("action_evidence_allowance_bytes")
        if len({item["name"] for item in capabilities}) != len(capabilities):
            statuses[node["key"]] = "invalid_semantic_node"
        else:
            node["required_capabilities"] = {item["name"]: item["minimum"] for item in capabilities}
            try:
                typed = DataflowNodeWireV23.model_validate(raw_node)
                node["success_criteria"] = [
                    item.criterion(typed.expected_artifact) for item in typed.success_criteria
                ]
                valid[node["key"]] = node
            except (ValueError, TypeError, ValidationError):
                statuses[node["key"]] = "invalid_criteria_node_not_measured"
        nodes.append(node)
    graph = {
        "nodes": nodes + list(completed_nodes),
        "edges": selected["edges"],
        **resource_limits,
        "coordination_reserve_tokens": coordination_reserve_tokens,
        "capacity_contract": {
            "version": VERSION,
            "input_inventory": inventory,
            "nodes": {},
            "input_acquisition_policy": "core-declared-source-prefetch-v1",
            "action_evidence_allowances": allowances,
        },
    }
    # Match the unchanged production's initial resource-sizing shape exactly.
    preserved_policy = (parent_graph or {}).get("serial_capacity_policy")
    if parent_graph is None:
        candidate = {
            **graph,
            "serial_capacity_policy": {
                "version": SERIAL_CAPACITY_VERSION,
                "shared_reserve_tokens": 1,
            },
        }
        try:
            if validate_serial_policy(candidate):
                graph = candidate
        except DomainError:
            pass
    elif preserved_policy:
        graph["serial_capacity_policy"] = copy.deepcopy(preserved_policy)
    for node in graph["nodes"]:
        if node["key"] in completed:
            continue
        measured = measure_required_sources(service.store, graph, node, inventory)
        node["capacity_bounds"]["max_source_receipt_bytes"] = (
            measured.required_source_receipt_bytes
            + SOURCE_METADATA_RESERVE_BYTES
            + allowances[node["key"]]
        )
    profiles = [
        model
        for model in service.store.list_models()[:100]
        if model.enabled and not model.quarantine_reason
    ]
    engine, observations = TeamComposerEngine(), []
    for node in nodes:
        key = node["key"]
        if key not in valid:
            observations.append({"node": key, "status": "unavailable", "reason": statuses[key]})
            continue
        role = RoleSpec(
            id="research",
            task_node_key=key,
            required_capabilities=node["required_capabilities"],
            tools=node["allowed_tools"],
            input_tokens=1,
            output_tokens=PLANNED_WORKER_OUTPUT_TOKENS,
            responsibility=node["objective"],
            input_contract=node["required_input_paths"] or [node["objective"]],
            output_schema=DEFAULT_OUTPUT_SCHEMA,
            acceptance_criteria=node["success_criteria"],
        )
        limits = CompositionLimits(
            max_members=1,
            max_concurrency=1,
            max_depth=1,
            max_total_tokens=2049,
            allowed_tools=node["allowed_tools"],
        )
        candidates, unavailable = [], 0
        with service.store.connection() as connection:
            connection.execute("PRAGMA query_only=ON")
            connection.execute("BEGIN")
            for model in profiles:
                try:
                    body = engine.compose([role], [model], limits, strategy="greedy")
                    body["members"][0]["input_acquisition_policy"] = (
                        "core-declared-source-prefetch-v1"
                    )
                    body["members"][0]["action_evidence_allowance_bytes"] = allowances[key]
                    selected_provider = (
                        service.capacity_providers.get(model.provider)
                        if service.capacity_providers
                        else provider
                    )
                    if (
                        getattr(
                            getattr(selected_provider, "config", None),
                            "id",
                            model.provider,
                        )
                        != model.provider
                    ):
                        raise DomainError("selected_provider_framing_unavailable")
                    _envelope, diagnostic = node_review_envelope(
                        service.store,
                        connection,
                        quest,
                        graph,
                        node,
                        body["members"][0],
                        selected_provider,
                        resource_sizing=True,
                        _diagnostic_only=True,
                    )
                    candidates.append(
                        {
                            **{
                                name: value for name, value in diagnostic.items() if name in NUMBERS
                            },
                            "violations": diagnostic["violations"],
                        }
                    )
                except (ValueError, TypeError, KeyError, DomainError):
                    unavailable += 1
        observations.append(
            {
                "node": key,
                "status": "available" if candidates else "unavailable",
                "candidates": candidates[:2],
                "omitted_candidates": max(0, len(candidates) - 2),
                "unmeasurable_candidates": unavailable,
            }
        )
    report = {
        "version": "planner-capacity-preview-v23",
        "status": "available",
        "scope": "diagnostic_only_valid_nodes_original_formulas_no_allocation_or_authority",
        "nodes": observations,
        "preserved_completed_keys": sorted(completed),
    }
    if len(json.dumps(report, ensure_ascii=False).encode()) > MAX_REPORT_BYTES:
        return _unavailable("complete_summary_outside_diagnostic_bound")
    return report


def preview_complete_capacity(*args, **kwargs):
    try:
        return _preview_complete_capacity(*args, **kwargs)
    except (OSError, KeyError, TypeError, ValueError, RecursionError, DomainError):
        return _unavailable("complete_measurement_unavailable")

"""Synthetic native input-acquisition framing, never tool execution evidence."""

from .worker_prompts import canonical


def measurement_call_id(index, *, action=False):
    return (
        ("measurement_action_" if action else "measurement_call_")
        + str(index).zfill(4)
        + "_"
        + "0" * 64
    )


def acquisition_assistant_frame(node):
    """Mirror the runtime's persisted assistant envelope for a bounded read batch.

    These labelled placeholders exist only inside measurement. No call, receipt,
    Worker message or result is created. Additional model exploration remains
    subject to cumulative runtime limits; this funds one declared read batch.
    """
    calls = [
        {"name": "file_read", "arguments": {"path": path}} for path in node["required_input_paths"]
    ] + [
        {"name": "worker_read_completed_delivery", "arguments": {"node_key": key}}
        for key in node.get("required_predecessor_deliveries") or []
    ]
    if not calls:
        return None
    return {
        "role": "assistant",
        "content": "",
        "tool_calls": [
            {
                "id": measurement_call_id(index),
                "type": "function",
                "function": {
                    "name": item["name"],
                    "arguments": canonical(item["arguments"]),
                },
            }
            for index, item in enumerate(calls)
        ],
    }


def acquisition_tool_history(node, receipts, workspace_root):
    """One native reply for each synthetic call; unknown future body stays {}.

    Future complete bodies are funded separately by the original source-growth
    formula. This never supplies those placeholders to runtime or a Provider.
    """
    from pathlib import Path

    known = {str(Path(item["resource_scope"]).resolve()): item for item in receipts}
    results = []
    for index, path in enumerate(node["required_input_paths"]):
        source = known.get(str((Path(workspace_root) / path).resolve()))
        output = {key: source["output"][key] for key in ("content", "sha256")} if source else {}
        results.append(
            {
                "role": "tool",
                "tool_call_id": measurement_call_id(index),
                "content": canonical(output),
            }
        )
    for index, _key in enumerate(
        node.get("required_predecessor_deliveries") or [], start=len(results)
    ):
        results.append(
            {
                "role": "tool",
                "tool_call_id": measurement_call_id(index),
                "content": "{}",
            }
        )
    return results


def prefetch_source_history(node, receipts, workspace_root):
    """Measure the exact Core user-data serializer without creating evidence.

    Known file bodies remain complete. Future bodies are explicit unknowns
    funded separately by the unchanged complete-source growth policy. This
    synthetic measurement never reaches runtime, storage or a Provider call.
    """
    from pathlib import Path

    from .worker_prefetch import source_message

    known = {str(Path(item["resource_scope"]).resolve()): item for item in receipts}
    entries = []
    selected = [("file_read", {"path": path}) for path in node["required_input_paths"]] + [
        ("worker_read_completed_delivery", {"node_key": key})
        for key in node.get("required_predecessor_deliveries") or []
    ]
    for index, (name, arguments) in enumerate(selected):
        source = (
            known.get(str((Path(workspace_root) / arguments["path"]).resolve()))
            if name == "file_read"
            else None
        )
        output = {key: source["output"][key] for key in ("content", "sha256")} if source else {}
        entries.append(
            {
                "ordinal": index,
                "tool_name": name,
                "arguments": arguments,
                "call_id": "core_source_" + "0" * 32,
                "receipt_id": "receipt_" + "0" * 32 if name == "file_read" else None,
                "result_sha256": "0" * 64,
                "output": output,
            }
        )
    return [source_message(entries)] if entries else []


def action_completion_stages(node, graph, workspace_root):
    """Frame minimal declared numeric/write completions; no action is performed.

    Empty bodies are explicit unknowns covered by canonical byte growth, never
    candidate code, results, receipts or evidence supplied to a Worker/model.
    Additional actions stay bounded and charged at runtime.
    """
    from pathlib import Path

    selected = []
    if "numeric_ast" in node["allowed_tools"]:
        producers = {edge["source"] for edge in graph["edges"] if edge["target"] == node["key"]}
        source_bound = min(
            16000,
            max(
                [
                    node["capacity_bounds"]["max_artifact_bytes"],
                    *[
                        item["capacity_bounds"]["max_artifact_bytes"]
                        for item in graph["nodes"]
                        if item["key"] in producers
                    ],
                ]
            ),
        )
        selected.append(
            (
                "numeric_ast",
                {"source": "", "inputs": {}},
                {
                    "exit_code": 0,
                    "stdout": "",
                    "stderr": "",
                    "source_sha256": "0" * 64,
                    "input_sha256": "0" * 64,
                    "result_json": "",
                    "steps": 1,
                    "subset": "forge_numeric_ast_v1",
                },
                source_bound,
            )
        )
    if "file_write" in node["allowed_tools"] and node.get("expected_artifact"):
        selected.append(
            (
                "file_write",
                {"path": node["expected_artifact"], "content": ""},
