import ast
import hashlib
import json
from pathlib import Path
root = Path.cwd()
p = root / '.local/phase2/final-goals-v23-draft.json'
doc = json.loads(p.read_text(encoding='utf-8'))
errors = []
if [g['number'] for g in doc['goals']] != list(range(1, 16)):
    errors.append('goal numbering')
if any(g['acceptance_status'] != 'pending_v23_actual_acceptance' for g in doc['goals']):
    errors.append('status')
cache = {}
def symbols(path):
    if path not in cache:
        tree = ast.parse((root / path).read_text(encoding='utf-8-sig'))
        found = set()
        def walk(body, prefix=''):
            for node in body:
                if isinstance(node, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                    name = prefix + node.name
                    found.add(name)
                    walk(node.body, name + '.')
        walk(tree.body)
        cache[path] = found
    return cache[path]
source_count = 0
test_count = 0
for goal in doc['goals']:
    for ref in goal['source_evidence']:
        for symbol in ref['symbols']:
            source_count += 1
            try:
                if symbol not in symbols(ref['path']):
                    errors.append(f"goal {goal['number']} missing symbol {ref['path']}::{symbol}")
            except Exception as exc:
                errors.append(f"goal {goal['number']} {ref['path']}: {type(exc).__name__}")
    for ref in goal['test_evidence']:
        test_count += 1
        path, name = ref.split('::', 1)
        if name not in symbols(path):
            errors.append(f"goal {goal['number']} missing test {ref}")
for item in doc['historical_evidence']:
    for path in item['paths']:
        if not (root / path).is_file():
            errors.append('missing history ' + path)
for path in [doc['preserved_previous_draft'],doc['v23_implementation_boundary']['owned_integration_index']]:
