"""Explicit new review contracts; legacy packets never acquire these bounds."""

import json

from .domain import DomainError

REVIEW_ENVELOPE_VERSION = "review-envelope-v1"
_FIELDS = {
    "version",
    "max_source_bytes",
    "max_artifact_bytes",
    "max_delivery_bytes",
    "max_review_input_tokens",
    "verdict_tokens",
    "correction_input_tokens",
    "correction_output_tokens",
    "correction_calls",
}


class ReviewEnvelopeError(DomainError):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _json(value):
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    )


def validate_review_envelope(value):
    """Return a copy of a fully explicit approved policy, without adding defaults."""
    if not isinstance(value, dict) or set(value) != _FIELDS:
        raise ReviewEnvelopeError("review_envelope_fields_invalid")
    if value["version"] != REVIEW_ENVELOPE_VERSION:
        raise ReviewEnvelopeError("review_envelope_version_invalid")
    for key in _FIELDS - {"version"}:
        if type(value[key]) is not int or value[key] < (
            0 if key in {"max_source_bytes", "max_artifact_bytes"} else 1
        ):
            raise ReviewEnvelopeError("review_envelope_bounds_invalid")
    if (
        any(
            value[key] > 65536
            for key in (
                "max_source_bytes",
                "max_artifact_bytes",
                "max_delivery_bytes",
                "max_review_input_tokens",
                "correction_input_tokens",
            )
        )
        or not 1024 <= value["verdict_tokens"] <= 8192
        or value["correction_output_tokens"] > 8192
        or value["correction_calls"] not in {1, 2}
        or sum(
            value[key] for key in ("max_source_bytes", "max_artifact_bytes", "max_delivery_bytes")
        )
        >= 65536
    ):
        raise ReviewEnvelopeError("review_envelope_bounds_invalid")
    return dict(value)


def review_cycle_reserve(envelope, *, reviews_remaining=2, correction_calls_remaining=None):
    """Policy reserve for two reviews and one correction, within existing limits.

    Runtime callers pass the remaining stages after settled reviews/revision;
    this never charges, refunds or restores any previously consumed allowance.
    """
    envelope = validate_review_envelope(envelope)
    calls = (
        envelope["correction_calls"]
        if correction_calls_remaining is None
        else correction_calls_remaining
    )
    if (
        type(reviews_remaining) is not int
        or not 0 <= reviews_remaining <= 2
        or type(calls) is not int
        or not 0 <= calls <= envelope["correction_calls"]
    ):
        raise ReviewEnvelopeError("review_cycle_stage_invalid")
    return reviews_remaining * (
        envelope["max_review_input_tokens"] + envelope["verdict_tokens"]
    ) + calls * (envelope["correction_input_tokens"] + envelope["correction_output_tokens"])


def review_cycle_state(connection, run_id, envelope):
    """Read remaining stages from durable starts and applied model-review revision.

    Refunded unsent reviews/corrections do not consume a stage. Unknown admitted
    calls retain their charge and consume a stage; no unknown usage is zeroed.
    """
    envelope = validate_review_envelope(envelope)
    starts = connection.execute(
        "SELECT payload FROM events e WHERE e.event_type='review.started' "
        "AND json_extract(e.payload,'$.run_id')=? AND NOT EXISTS("
        "SELECT 1 FROM events r WHERE r.event_type='review.released' "
        "AND json_extract(r.payload,'$.call_id')=json_extract(e.payload,'$.call_id') "
        "AND json_extract(r.payload,'$.reservation_refunded')=1 "
        "AND NOT EXISTS(SELECT 1 FROM events l WHERE l.event_type='review.late_settlement' "
        "AND json_extract(l.payload,'$.call_id')=json_extract(e.payload,'$.call_id')))",
        (run_id,),
    ).fetchall()
    revision = connection.execute(
        "SELECT e.created_at FROM events e JOIN events r "
        "ON r.id=json_extract(e.payload,'$.review_event_id') "
        "WHERE e.event_type='worker.revision_requested' "
        "AND json_extract(e.payload,'$.run_id')=? "
        "AND r.event_type='review.result' "
        "AND json_extract(r.payload,'$.review_context')='independent_same_model' "
        "AND json_extract(r.payload,'$.verdict')='NEEDS_REVISION' ORDER BY e.seq LIMIT 1",
        (run_id,),
    ).fetchone()
    corrections = 0
    if revision:
        corrections = connection.execute(
            "SELECT count(*) FROM worker_model_reservations WHERE run_id=? "
            "AND created_at>=? AND state!='refunded'",
            (run_id, revision[0]),
        ).fetchone()[0]
    reviews_remaining = max(0, 2 - len(starts))
    calls_remaining = max(0, envelope["correction_calls"] - corrections)
    return {
        "reviews_remaining": reviews_remaining,
        "correction_calls_remaining": calls_remaining,
        "future_reserve_tokens": review_cycle_reserve(
            envelope,
            reviews_remaining=reviews_remaining,
            correction_calls_remaining=calls_remaining,
        ),
        "correction_started": revision is not None,
    }


def review_packet_sizes(packet):
    artifact_bytes = 0
    for item in packet["artifacts"]:
        if "content" in item:
            artifact_bytes += len(_json(item["content"]).encode("utf-8"))
        elif (
            type(item.get("canonical_content_bytes")) is int
            and item["canonical_content_bytes"] >= 0
        ):
            artifact_bytes += item["canonical_content_bytes"]
        else:
            raise ReviewEnvelopeError("review_artifact_size_unknown")
    source_bytes = len(_json(packet["receipts"]).encode("utf-8"))
    if "predecessor_deliveries" in packet:
        if not isinstance(packet["predecessor_deliveries"], list):
            raise ReviewEnvelopeError("review_predecessor_delivery_size_unknown")
        source_bytes += len(_json(packet["predecessor_deliveries"]).encode("utf-8"))
    return {
        "source_bytes": source_bytes,
        "artifact_bytes": artifact_bytes,
        "delivery_bytes": len(_json(packet["delivery"]).encode("utf-8")),
    }


def validate_review_packet(packet, envelope):
    envelope = validate_review_envelope(envelope)
    sizes = review_packet_sizes(packet)
    for component, size in sizes.items():
        if size > envelope["max_" + component]:
            raise ReviewEnvelopeError("review_" + component + "_envelope_exceeded")
    return sizes


def project_review_text(packet):
    """A reversible wire view; every original character remains available once.

    Choose a reference key absent from every original object, including hostile
    artifact data. This prevents original objects being mistaken for references.
    """
    keys = set()

    def collect(value):
        if isinstance(value, dict):
            keys.update(value)
            for item in value.values():
                collect(item)
        elif isinstance(value, list):
            for item in value:
                collect(item)

    collect(packet)
    marker = "$review_text"
    while marker in keys:
        marker += "_"
    texts, indices = [], {}

    def project(value):
        if isinstance(value, str) and len(value.encode("utf-8")) >= 512:
            if value not in indices:
                indices[value] = len(texts)
                texts.append(value)
            return {marker: indices[value]}
        if isinstance(value, dict):
            return {key: project(item) for key, item in value.items()}
        if isinstance(value, list):
            return [project(item) for item in value]
        return value

    projected = project(packet)
    return {"reference_key": marker, "packet": projected}, texts


def restore_review_text(view, texts):
    """Deterministically recover the exact canonical packet from its wire view."""
    marker = view["reference_key"]

    def restore(value):
        if isinstance(value, dict):
            if set(value) == {marker}:
                index = value[marker]
                if type(index) is not int or not 0 <= index < len(texts):
                    raise ReviewEnvelopeError("review_text_reference_invalid")
                return texts[index]
            return {key: restore(item) for key, item in value.items()}
        if isinstance(value, list):
            return [restore(item) for item in value]
        return value

    return restore(view["packet"])

"""Explicit serial capacity sharing without increasing any durable budget."""

import json
import os
from pathlib import Path
from types import SimpleNamespace

from .domain import DomainError

SERIAL_CAPACITY_VERSION = "serial-capacity-v1"


def validate_serial_policy(graph):
    policy = graph.get("serial_capacity_policy")
    if policy is None:
        return None
    if (
        not isinstance(policy, dict)
        or set(policy) != {"version", "shared_reserve_tokens"}
        or policy["version"] != SERIAL_CAPACITY_VERSION
        or type(policy["shared_reserve_tokens"]) is not int
        or not 1 <= policy["shared_reserve_tokens"] <= 1000000
        or graph.get("max_cost_microunits") is not None
        or graph.get("cost_currency") is not None
    ):
        raise DomainError("Serial capacity requires an explicit bounded token-only reserve")
    nodes = graph["nodes"]
    keys = {node["key"] for node in nodes}
    edges = graph["edges"]
    incoming, outgoing = dict.fromkeys(keys, 0), dict.fromkeys(keys, 0)
    for edge in edges:
        if (
            edge["condition"] != "success"
            or edge["source"] not in keys
            or edge["target"] not in keys
        ):
            raise DomainError("Serial capacity requires one strict success chain")
        incoming[edge["target"]] += 1
        outgoing[edge["source"]] += 1
    if (
        len(keys) != len(nodes)
        or len(nodes) < 2
        or len(edges) != len(nodes) - 1
        or max(incoming.values(), default=0) > 1
        or max(outgoing.values(), default=0) > 1
        or sum(value == 0 for value in incoming.values()) != 1
        or sum(value == 0 for value in outgoing.values()) != 1
    ):
        raise DomainError("Serial capacity requires one strict success chain")
    cursor = next(key for key, count in incoming.items() if count == 0)
    seen = set()
    while cursor is not None and cursor not in seen:
        seen.add(cursor)
        cursor = next((edge["target"] for edge in edges if edge["source"] == cursor), None)
    if seen != keys or cursor is not None:
        raise DomainError("Serial capacity requires a connected acyclic success chain")
    reserve = graph.get("coordination_reserve_tokens")
    if (
        type(reserve) is not int
        or reserve < (graph["max_total_tokens"] + 9) // 10
        or sum(node["budget_tokens"] for node in nodes) + policy["shared_reserve_tokens"] + reserve
        > graph["max_total_tokens"]
    ):
        raise DomainError(
            "Serial baselines, one shared reserve and coordination exceed original cap"
        )
    return dict(policy)


def node_execution_limit(graph, node):
    policy = validate_serial_policy(graph)
    return node["budget_tokens"] + (policy["shared_reserve_tokens"] if policy else 0)


def serial_start_allowance(store, connection, quest, plan, node, member, ledger=None):
    """Read-only admission from settled usage; caller retains its execution fence.

    The returned ceiling is a subset of the approved per-member maximum. It is
    not a new allocation, charge, refund, predicted usage or permission to run.
    """
    from .capacity_preflight import coordination_budget_snapshot
    from .model_call_budget import ModelCallBudgetLedger

    if not connection.in_transaction:
        raise DomainError("Serial admission requires a caller-owned execution transaction")

    plan = dict(plan)
    graph = json.loads(plan["graph_json"]) if "graph_json" in plan else plan
    policy = validate_serial_policy(graph)
    if policy is None:
        raise DomainError("Serial Worker requires its approved serial capacity policy")
    key = member["task_node_key"]
    contracts = [item for item in graph["nodes"] if item["key"] == key]
    if len(contracts) != 1:
        raise DomainError("Serial Worker task contract unavailable")
    contract = contracts[0]
    if (
        not isinstance(ledger, ModelCallBudgetLedger)
        or os.path.normcase(str(Path(ledger.path).resolve()))
        != os.path.normcase(str(Path(store.path).resolve()))
        or ledger.cost_limit is not None
        or min(
            ledger.token_limit,
            ledger.scope_limits.get(("quest", quest["id"]), (ledger.token_limit, 1))[0],
        )
        > graph["max_total_tokens"]
    ):
        raise DomainError("Serial Worker requires the original durable Gateway budget ledger")
    maximum = node_execution_limit(graph, contract)
    if (
        member.get("serial_capacity_policy") != policy
        or member.get("execution_token_limit") != maximum
        or member["estimated_tokens"] != contract["budget_tokens"]
    ):
        raise DomainError("Serial member capacity differs from its approved plan")
    if connection.execute(
        "SELECT 1 FROM worker_runs WHERE quest_id=? AND state IN ('queued','running','paused','blocked','review_pending') LIMIT 1",
        (quest["id"],),
    ).fetchone():
        raise DomainError("Serial capacity cannot overlap an active Worker or review")
    model_table = connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name='model_budget_attempts'"
    ).fetchone()
    if (
        model_table
        and connection.execute(
            "SELECT 1 FROM model_budget_attempts WHERE quest_id=? AND "
            "(state!='settled' OR input_charged IS NULL OR output_charged IS NULL) LIMIT 1",
            (quest["id"],),
        ).fetchone()
    ):
        raise DomainError("Serial capacity requires every prior model attempt fully settled")
    states = {
        row["node_key"]: row["status"]
        for row in connection.execute(
            "SELECT node_key,status FROM task_nodes WHERE plan_id=?", (plan["id"],)
        )
    }
    pending = {item["key"] for item in graph["nodes"] if states.get(item["key"]) != "succeeded"}
    if key not in pending:
        raise DomainError("Serial Worker node already completed")
    if any(
        edge["target"] == key and states.get(edge["source"]) != "succeeded"
        for edge in graph["edges"]
    ):
        raise DomainError("Serial Worker success predecessor is not completed")
    from .evidence import CompletionGate

    for edge in graph["edges"]:
        if edge["target"] == key:
            predecessor = connection.execute(
                "SELECT * FROM task_nodes WHERE plan_id=? AND node_key=?",
                (plan["id"], edge["source"]),
            ).fetchone()
            CompletionGate(store)._check_live_node(
                SimpleNamespace(connection=connection), quest, plan, predecessor
            )
    future = sum(item["budget_tokens"] for item in graph["nodes"] if item["key"] in pending - {key})
    budget = coordination_budget_snapshot(connection, store, quest["id"], graph, ledger)
    available = max(0, budget["max_worker_allocations_now"] - future)
    observation = graph.get("capacity_contract", {}).get("nodes", {}).get(key, {})
    minimum = observation.get("minimum_node_tokens")
    selected_minimum = member.get("capacity_preflight", {}).get("minimum_node_tokens")
    if type(selected_minimum) is not int or selected_minimum < 1:
        raise DomainError("Serial selected member has no complete capacity measurement")
    minimum = max(minimum, selected_minimum) if type(minimum) is int else None
    if (
        type(minimum) is not int
        or minimum < 1
        or available < max(minimum, contract["budget_tokens"])
    ):
        raise DomainError(
            "Serial remaining budget cannot fund current full cycle and future baselines"
        )
    return {
        "version": SERIAL_CAPACITY_VERSION,
        "execution_token_limit": min(maximum, available),
        "approved_execution_token_limit": maximum,
        "baseline_tokens": contract["budget_tokens"],
        "shared_reserve_tokens": policy["shared_reserve_tokens"],
        "minimum_current_cycle": minimum,
        "future_baseline_tokens": future,
