                raw[ref] = {"table": table, "row": dict(row), "row_sha256": sha(canonical(dict(row)).encode())}
    service = MemoryService(_ReadOnlyStore(Path(workspace).resolve()))
    eligible = {}
    for ref in sorted(refs):
        items = service.retrieve_context("", source_refs=[ref], exact_source_refs=True, limit=1, max_bytes=65536)["items"]
        if items:
            eligible[ref] = {"item": items[0], "item_sha256": sha(canonical(items[0]).encode()), "raw": raw.get(ref)}
    return {"quest_id": quest_id, "original_user": original_user, "original_user_sha256": sha(canonical(original_user).encode()), "eligible": eligible}


def validate_plan(plan, spec, index):
    nodes = plan.get("nodes", [])
    if len(nodes) != 1 or plan.get("edges") or plan.get("serial_capacity_policy") is not None:
        raise ValueError("Requires exactly one independent node")
    node = nodes[0]
    if set(node.get("allowed_tools", [])) != {"file_read"} or node.get("expected_artifact") is not None or node.get("success_criteria") != ["delivery_review"]:
        raise ValueError("Read-only actual source review contract required")
    if index == 1 and node.get("required_input_paths") != [SOURCE_PATH]:
        raise ValueError("First task original input must remain declared")
    if index == 2 and node.get("required_input_paths"):
        raise ValueError("Second prompt cannot fabricate a verified initial inventory")
    if plan.get("max_total_tokens", 0) > LIMITS["max_total_tokens"] or not 0 < (plan.get("max_duration_seconds") or 0) <= 600:
        raise ValueError("Original task cap/duration changed")
    if not 0 < node.get("capacity_bounds", {}).get("max_delivery_bytes", 0) <= 2048:
        raise ValueError("Complete compact delivery bound required")


def audit_record(record):
    spec, workspace = record["original_spec"], record["original_spec"]["workspace"]
    failures, tasks = [], []
    quest_ids = record.get("quest_ids", [])
    if len(quest_ids) != 2 or len(set(quest_ids)) != 2:
        return {"passed": False, "failures": ["two_distinct_quests_required"]}
    evidence = collect(workspace, quest_ids[-1])
    if len(evidence["quests"]) != 2 or any(q["status"] != "completed" for q in evidence["quests"]):
        failures.append("both_actual_quests_must_complete")
    for quest_id in quest_ids:
        item = collect(workspace, quest_id)
        passes = independent_passes(item, PROVIDER_ID, MODEL_ID)
        if len(item["workers"]) != 1 or len(passes) != 1 or not item["router_completion_notice"]:
            failures.append("actual_current_independent_pass_or_notice_missing:" + quest_id)
        if any(receipt_errors(action) for action in item["actions"]) or item["core_source_errors"]:
            failures.append("invalid_actual_source_receipts:" + quest_id)
        reads = []
        for action in item["actions"]:
            if action["tool_name"] == "file_read" and action["intent_state"] == "succeeded":
                output = json.loads(action["result_json"])
                if output.get("sha256") == spec["inputs"][0]["sha256"] and Path(output.get("path", "")).resolve() == (Path(workspace) / SOURCE_PATH).resolve():
                    reads.append(action["receipt_id"])
        if not reads:
            failures.append("actual_original_source_read_missing:" + quest_id)
        tasks.append({"quest_id": quest_id, "passes": passes, "verified_original_source_receipts": reads})
    attempts = evidence["attempts"]
    unknown = [a["attempt_id"] for a in attempts if not known_settled(a)]
    total = sum((a["input_charged"] or 0) + (a["output_charged"] or 0) for a in attempts)
    if unknown or total > 360000:
        failures.append("unresolved_usage_or_original_global_cap_exceeded")
    if evidence["conversation_count"] != 1 or evidence["router"][0]["router_session_id"] != record.get("initial_router_identity"):
        failures.append("persistent_router_conversation_changed")
    if sha((Path(workspace) / SOURCE_PATH).read_bytes()) != spec["inputs"][0]["sha256"]:
        failures.append("original_input_changed")
    compaction = record.get("compaction", {})
    if not compaction.get("archive_created") or not compaction.get("source_readback_available") or not any(s["source_id"] == record["source_snapshot_before"]["original_user"]["id"] for s in compaction.get("verified_sources", [])):
        failures.append("actual_first_source_compaction_readback_missing")
    target = record.get("results", {}).get("task2_message", {}).get("body", {})
    retrieved = target.get("assistant_message", {}).get("metadata", {}).get("cycle", {}).get("retrieved_sources", [])
    before = record.get("source_snapshot_before", {}).get("eligible", {})
    after = source_snapshot(workspace, quest_ids[0])["eligible"]
    used = []
    for ref, value in before.items():
        item = value["item"]
        if ref in retrieved or item["id"] in retrieved:
            current = after.get(ref)
            if current and current["item_sha256"] == value["item_sha256"] and current["raw"] == value["raw"] and item.get("status") == "hypothesis":
                used.append({"source_ref": ref, "item_sha256": value["item_sha256"], "raw_sha256": value["raw"]["row_sha256"] if value["raw"] else None, "status": item["status"], "source_type": item.get("source_type"), "source_refs": item["source_refs"]})
    if not used:
        failures.append("original_eligible_hypothesis_not_used_by_target_router")
    semantic = [a for a in attempts if a["purpose"] == "memory_semantic_retrieval" and a["created_at"] >= record.get("task2_sent_at", "~") and known_settled(a)]
    if not semantic:
        failures.append("target_actual_semantic_recall_attempt_missing")
    with readonly(workspace) as db:
        second = dict(db.execute("SELECT * FROM quests WHERE id=?", (quest_ids[1],)).fetchone())
        final = db.execute("SELECT payload FROM events WHERE quest_id=? AND event_type='worker.result' ORDER BY seq DESC LIMIT 1", (quest_ids[1],)).fetchone()
        delivery = json.loads(json.loads(final[0])["claim"]) if final else {}
    combined = canonical(delivery)
    if SOURCE_PATH not in second["goal"] or "fifteen" not in second["goal"].casefold() and "15" not in second["goal"]:
        failures.append("recovered_reference_rule_missing_from_target_goal")
    for expected in ("0.7", "12", "3", "15", DOCUMENT["limitation"], spec["inputs"][0]["sha256"]):
        if expected not in combined:
            failures.append("target_delivery_missing_current_checked_content:" + expected[:32])
    if not any(word in combined.casefold() for word in ("ship", "ready", "recommend", "release", "发布", "就绪")):
        failures.append("target_recommendation_missing")
    return {"passed": not failures, "failures": failures, "tasks": tasks, "used_original_memory": used, "retrieved_source_ids": retrieved, "target_semantic_attempts": semantic, "target_goal": second["goal"], "target_delivery": delivery, "usage": {"known_total_tokens": total, "unknown_attempt_ids": unknown}, "limitations": spec["limitations"]}


def run(spec_path, expected_spec, expected_code):
    spec_path = Path(spec_path).resolve()
    spec = json.loads(spec_path.read_text(encoding="utf-8"))
    workspace = Path(spec["workspace"])
    if sha(spec_path.read_bytes()) != expected_spec or spec["version"] != VERSION or spec["driver_snapshot"] != driver_snapshot() or spec["code_snapshot"] != code_snapshot() or expected_code != spec["code_snapshot"]["sha256"]:
        raise ValueError("Explicit original spec/driver/frozen code binding mismatch")
    if workspace.resolve() != (spec_path.parent / "workspace") or (workspace / "data/forge.sqlite3").exists() or (spec_path.parent / "run.json").exists():
        raise ValueError("Requires fresh isolated unreplayed workspace")
    if tuple(prompts()) != (spec["first_prompt"], spec["second_prompt"]) or spec["limits_each_quest"] != LIMITS or sha((workspace / SOURCE_PATH).read_bytes()) != spec["inputs"][0]["sha256"]:
        raise ValueError("Original source/prompt/limits changed")
    record = {"started_at": now(), "original_spec": spec, "spec_sha256": expected_spec, "results": {}, "quest_ids": [], "failures": []}
    output = spec_path.parent / "run.json"
    write_json(output, record, new=True)
    core, sensitive = None, []
    started = time.monotonic()
    def persist():
        encoded = json.dumps(record, ensure_ascii=False, indent=2, allow_nan=False)
        for value in sensitive:
            if value:
                encoded = encoded.replace(value, "[REDACTED]")
        output.write_text(encoded + "\n", encoding="utf-8")
    def call(label, method, path, payload=None):
        response = core.call(method, path, payload, timeout=120)
        record["results"][label] = response
        persist()
        if response["status"] not in {200, 201}:
            raise ValueError("API rejected " + label)
        return response["body"]
    def wait(read, seconds=180):
        deadline = min(started + 1140, time.monotonic() + seconds)
        while time.monotonic() < deadline:
            value = read()
            if value:
                return value
            time.sleep(1)
        raise TimeoutError("Bounded memory-probe stage exhausted")
    try:
        key = os.environ.get("FORGE_PROVIDER_KEY_LIVE_TEST")
        if not key:
            raise ValueError("Credential must exist only in process environment")
        sensitive.append(key)
        core = LiveCore(workspace, provider_env=provider_env_from_key(key), token_limit=360000, concurrency=1, log=spec_path.parent / "core.log")
        sensitive.append(core.secret)
        core.start()
        sensitive.append(core.bearer)
        record["initial_router_identity"] = call("conversation", "GET", "/api/conversation")["router"]["router_session_id"]
        call("register", "POST", "/api/models", MODEL_PROFILE)
        for index, prompt in enumerate(prompts(), 1):
            task_started = time.monotonic()
            if index == 2:
                record["task2_sent_at"] = now()
            response = call(f"task{index}_message", "POST", "/api/conversation/message", {"content": prompt, "request_id": spec["run_id"] + f"-m{index}"})
            quest_id = response.get("quest_id")
            if not quest_id or quest_id in record["quest_ids"]:
                raise ValueError("Router must create two distinct actual Quests")
            record["quest_ids"].append(quest_id)
            if index == 2:
                record["source_snapshot_after_router"] = source_snapshot(workspace, record["quest_ids"][0])
            def plan_ready():
                response = core.call("GET", f"/api/quests/{quest_id}/plan", timeout=15)
                if response["status"] == 200:
                    return response["body"].get("plan", response["body"])
                if terminal_planning_failure(workspace, quest_id):
                    raise ValueError("Terminal Planner failure")
            plan = wait(plan_ready)
            validate_plan(plan, spec, index)
            record[f"task{index}_plan"] = plan
            version = call(f"task{index}_before_plan", "GET", f"/api/quests/{quest_id}")["quest"]["version"]
            call(f"task{index}_approve_plan", "POST", f"/api/quests/{quest_id}/plan/approve", {"digest": plan["digest"], "plan_revision": plan["revision"], "expected_version": version})
            def team_ready():
                response = core.call("GET", f"/api/quests/{quest_id}/teams", timeout=15)
                if response["status"] == 200:
                    body = response["body"]
                    for item in body if isinstance(body, list) else body.get("items", body.get("proposals", [])):
                        if item.get("status") == "proposed":
                            return item
                if terminal_composition_failure(workspace, quest_id):
                    raise ValueError("Terminal Composer failure")
            team = wait(team_ready)
            members = team.get("body", {}).get("members", [])
            if len(members) != 1 or set(members[0]["tool_scope"]) != {"file_read"} or members[0]["provider_id"] != PROVIDER_ID or members[0]["model_id"] != MODEL_ID:
                raise ValueError("Unexpected team identity/scope")
            record[f"task{index}_team"] = team
            version = call(f"task{index}_before_team", "GET", f"/api/quests/{quest_id}")["quest"]["version"]
            call(f"task{index}_approve_team", "POST", f"/api/quests/{quest_id}/teams/approve", {"plan_revision": team["plan_revision"], "proposal_digest": team["proposal_digest"], "expected_version": version})
            def completed():
                item = core.call("GET", f"/api/quests/{quest_id}", timeout=15)["body"]
                if item["quest"]["status"] == "completed":
                    return item
                if item["quest"]["status"] in {"failed", "blocked", "cancelled"} or remaining_execution_blocked(continuity_snapshot(workspace, quest_id)):
                    raise ValueError("Actual Quest did not complete")
            record[f"task{index}_completion"] = wait(completed, seconds=540)
            wait(lambda: collect(workspace, quest_id)["router_completion_notice"], seconds=20)
            record[f"task{index}_duration_seconds"] = time.monotonic() - task_started
            if record[f"task{index}_duration_seconds"] > 600:
                raise ValueError("Original per-task duration exceeded")
            if index == 1:
                record["source_snapshot_before"] = source_snapshot(workspace, quest_id)
                core.stop()
                record["compaction"] = compact_stopped_core(core)
                core.start()
                sensitive.append(core.bearer)
                if call("conversation_after_compaction", "GET", "/api/conversation")["router"]["router_session_id"] != record["initial_router_identity"]:
                    raise ValueError("Router identity changed")
            persist()
    except BaseException as exc:
        record["failures"].append(type(exc).__name__ + ":" + str(exc))
    finally:
        if core:
            core.stop()
        record["duration_seconds"] = time.monotonic() - started
        record["finished_at"] = now()
        if record["duration_seconds"] > 1200:
            record["failures"].append("original_whole_run_duration_exceeded")
        try:
            record["audit"] = audit_record(record)
        except BaseException as exc:
            record["audit"] = {"passed": False, "failures": ["audit_failed:" + type(exc).__name__]}
        record["final_code_snapshot"] = code_snapshot()
        if record["final_code_snapshot"] != spec["code_snapshot"] or driver_snapshot() != spec["driver_snapshot"]:
            record["failures"].append("frozen_source_or_driver_changed")
        record["passed"] = not record["failures"] and record["audit"]["passed"]
        persist()
    return {"run_path": str(output), "passed": record["passed"], "failures": record["failures"], "audit_failures": record["audit"].get("failures")}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("prepare")
    run_parser = sub.add_parser("run")
    run_parser.add_argument("--prepared", required=True, type=Path)
    run_parser.add_argument("--expect-spec-sha256", required=True)
    run_parser.add_argument("--expect-code-snapshot", required=True)
    audit_parser = sub.add_parser("audit")
    audit_parser.add_argument("--run", required=True, type=Path)
    args = parser.parse_args()
    result = prepare() if args.command == "prepare" else run(args.prepared, args.expect_spec_sha256, args.expect_code_snapshot) if args.command == "run" else audit_record(json.loads(args.run.read_text(encoding="utf-8")))
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 1 if result.get("passed") is False else 0


if __name__ == "__main__":
    raise SystemExit(main())

