"""Explicit model-selected capacity profiles; exact decoding to the V23 contract."""

from typing import Annotated, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

from .graph_domain import CapabilityWire, _strict_wire_schema
from .planner_dataflow import DataflowDependencyWire
from .planner_dataflow_v23 import DataflowGraphWireV23, DataflowNodeWireV23, DataflowVerifierWireV23

OUTPUT_PROFILES = {
    "inline_1536": (1, 1536),
    "inline_2048": (1, 2048),
    "artifact_2048_delivery_1536": (2048, 1536),
    "artifact_3072_delivery_1536": (3072, 1536),
}
ACTION_PROFILES = {
    "declared_sources_only_0": 0,
    "small_receipts_1024": 1024,
    "bounded_test_receipts_4096": 4096,
}


class ProfileModel(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True, json_schema_extra=_strict_wire_schema)


class OutputProfile(ProfileModel):
    profile: Literal[
        "inline_1536",
        "inline_2048",
        "artifact_2048_delivery_1536",
        "artifact_3072_delivery_1536",
    ] = Field(
        description="Choose only when the entire assigned result fits. Inline creates no artifact; otherwise choose sufficient custom bounds. No default."
    )

    def bounds(self):
        artifact, delivery = OUTPUT_PROFILES[self.profile]
        return {"max_artifact_bytes": artifact, "max_delivery_bytes": delivery}


class CustomOutputProfile(ProfileModel):
    profile: Literal["custom"]
    max_artifact_bytes: int = Field(ge=1, le=32768)
    max_delivery_bytes: int = Field(ge=1, le=32768)

    def bounds(self):
        return self.model_dump(exclude={"profile"})


class ActionProfile(ProfileModel):
    profile: Literal[
        "declared_sources_only_0", "small_receipts_1024", "bounded_test_receipts_4096"
    ] = Field(
        description="New receipt output beyond complete declared initial sources: 0 for inline declared-source analysis, 1024 for small receipts, 4096 for bounded numeric/test receipts, or sufficient custom. No tool authority or default."
    )

    def allowance(self):
        return ACTION_PROFILES[self.profile]


class CustomActionProfile(ProfileModel):
    profile: Literal["custom"]
    action_evidence_allowance_bytes: int = Field(ge=0, le=32768)

    def allowance(self):
        return self.action_evidence_allowance_bytes


OutputCapacity = Annotated[OutputProfile | CustomOutputProfile, Field(discriminator="profile")]
ActionEvidence = Annotated[ActionProfile | CustomActionProfile, Field(discriminator="profile")]


class DataflowNodeWireV25(ProfileModel):
    key: str = Field(min_length=1, max_length=100, pattern=r"^[A-Za-z0-9_-]+$")
    objective: str = Field(min_length=1, max_length=2000)
    success_criteria: list[DataflowVerifierWireV23] = Field(min_length=1, max_length=5)
    required_capabilities: list[CapabilityWire]
    expected_artifact: str | None = Field(max_length=2000)
    max_attempts: int = Field(ge=1, le=10)
    allowed_tools: list[str] = Field(max_length=32)
    verified_input_paths: list[str] = Field(max_length=32)
    predecessors: list[DataflowDependencyWire] = Field(max_length=8)
    output_capacity: OutputCapacity
    action_evidence: ActionEvidence

    def v23_data(self):
        value = self.model_dump(exclude={"output_capacity", "action_evidence"})
        value["capacity_bounds"] = {
            **self.output_capacity.bounds(),
            "action_evidence_allowance_bytes": self.action_evidence.allowance(),
        }
        return value

    @model_validator(mode="after")
    def exact_semantics(self):
        if isinstance(self.output_capacity, OutputProfile):
            inline = self.output_capacity.profile.startswith("inline_")
            if inline != (self.expected_artifact is None):
                raise ValueError("capacity_profile_must_match_explicit_artifact_contract")
        DataflowNodeWireV23.model_validate(self.v23_data())
        return self


class DataflowGraphWireV25(ProfileModel):
    allocation_mode: Literal["core_measured"]
    nodes: list[DataflowNodeWireV25] = Field(min_length=1, max_length=8)

    def decoded(self):
        return DataflowGraphWireV23.model_validate(
            {
                "allocation_mode": self.allocation_mode,
                "nodes": [node.v23_data() for node in self.nodes],
            }
        )

    def proposal_data(self, **kwargs):
        graph = self.decoded().proposal_data(**kwargs)
        graph["capacity_contract"]["planner_capacity_choices"] = {
            node.key: {
                "output_capacity": node.output_capacity.model_dump(),
                "action_evidence": node.action_evidence.model_dump(),
            }
            for node in self.nodes
        }
        return graph


class CapacityChoice(ProfileModel):
    output_capacity: OutputCapacity
    action_evidence: ActionEvidence


def validate_capacity_choices(graph):
    """Provenance must match effective bounds; it grants no additional authority."""
    contract = graph.get("capacity_contract") or {}
    choices = contract.get("planner_capacity_choices")
    if choices is None:
        return
    completed = set(contract.get("preserved_completed_keys") or [])
    pending = {node["key"]: node for node in graph["nodes"] if node["key"] not in completed}
    if not isinstance(choices, dict) or set(choices) != set(pending):
        raise ValueError("planner_capacity_choices_require_exact_pending_nodes")
    allowances = contract.get("action_evidence_allowances")
    if not isinstance(allowances, dict):
        raise TypeError("planner_capacity_choices_require_original_allowances")
    for key, selected in choices.items():
        choice = CapacityChoice.model_validate(selected)
        bounds = pending[key].get("capacity_bounds") or {}
        if isinstance(choice.output_capacity, OutputProfile):
            inline = choice.output_capacity.profile.startswith("inline_")
            if inline != (pending[key].get("expected_artifact") is None):
                raise ValueError("capacity_profile_must_match_explicit_artifact_contract")
        if (
            any(
                bounds.get(field) != value
                for field, value in choice.output_capacity.bounds().items()
            )
            or allowances.get(key) != choice.action_evidence.allowance()
        ):
            raise ValueError("planner_capacity_choice_differs_from_effective_bounds")
"""Production Composer semantics bound to previously approved Core resources.

This adapter proposes no permissions, changes no plan, and performs no model
selection. TeamCompositionService must still validate the resulting proposal,
remeasure the selected Provider request, and require normal user approval.
Legacy TeamWire and manual proposal callers retain their original allocations.
"""

from typing import Literal

from pydantic import BaseModel, ConfigDict, Field

from .budget_policy import validate_serial_policy
from .domain import DomainError
from .hierarchical_plans import node_depth
from .team_composition import TeamCapabilityWire, TeamWire


class InvalidTeamProposal(DomainError):
    """Two settled production Composer responses failed deterministic admission."""


def uses_core_composer_resources(graph):
    contract = graph.get("capacity_contract") or {}
    return (
        contract.get("version") == "verified-capacity-v1"
        and (contract.get("resource_allocation") or {}).get("mode") == "core_measured"
        and bool(contract.get("nodes"))
        and all(
            type(item.get("output_bound")) is int and item["output_bound"] > 0
            for item in contract["nodes"].values()
        )
    )


class SemanticTeamRoleWire(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    id: str = Field(min_length=1, max_length=100)
    task_node_key: str = Field(min_length=1, max_length=100)
    required_capabilities: list[TeamCapabilityWire] = Field(max_length=32)
    tools: list[str] = Field(max_length=32)
    dynamic: bool
    responsibility: str = Field(min_length=1, max_length=2000)
    input_contract: list[str] = Field(max_length=20)
    output_schema_json: str | None = Field(
        description="Explicit null selects the supplied Core strict eight-field delivery schema."
    )
    acceptance_criteria: list[str] = Field(max_length=20)


class SemanticTeamWire(BaseModel):
    model_config = ConfigDict(extra="forbid", strict=True)
    roles: list[SemanticTeamRoleWire] = Field(min_length=1, max_length=16)
    strategy: Literal["single_model", "greedy", "coverage", "complementarity"]

    def inputs(self, graph, *, operator_max_concurrency):
        """Bind exact approved output/baseline; normal service admission follows.

        Source limits remain ceilings. Steps/tools use bounded Core defaults when
        no source limit exists; duration is divided within the approved total.
        The shared serial reserve appears once in the team limit and never in
        role allocations. Execution limits remain the service's responsibility.
        """
        if not uses_core_composer_resources(graph):
            raise DomainError("Core Composer requires approved measured output bounds")
        if type(operator_max_concurrency) is not int or operator_max_concurrency < 1:
            raise DomainError("Core Composer requires an operator concurrency ceiling")
        nodes = {node["key"]: node for node in graph["nodes"]}
        keys = [role.task_node_key for role in self.roles]
        if len(set(keys)) != len(keys) or set(keys) - set(nodes):
            raise DomainError("Each approved task node requires exactly one team member")
        maximum = (graph.get("execution_constraints") or {}).get("limits", {})
        count = len(self.roles)
        if count > min(16, maximum.get("max_members", 16)):
            raise DomainError("Team max_members exceeds source-bound task limit")
        serial = validate_serial_policy(graph)
        concurrency = (
            1
            if serial
            else min(count, operator_max_concurrency, maximum.get("max_concurrency", count))
        )
        duration = min(
            graph.get("max_duration_seconds") or 120 * count,
            maximum.get("max_duration_seconds", 120 * count),
            3600 * count,
        )
        if type(duration) is not int or duration < count:
            raise DomainError("Approved duration cannot fund every team member")
        per_role_duration, extra = divmod(duration, count)
        duration_by_key = {
            key: per_role_duration + (index < extra) for index, key in enumerate(sorted(keys))
        }
        steps = min(32, maximum.get("max_worker_steps", 16))
        calls = min(64, maximum.get("max_worker_tool_calls", 16))
        roles = []
        observations = graph["capacity_contract"]["nodes"]
        for wire in self.roles:
            node = nodes[wire.task_node_key]
            output = observations.get(wire.task_node_key, {}).get("output_bound")
            baseline = node["budget_tokens"]
            if type(output) is not int or not 0 < output < baseline:
                raise DomainError("Approved measured output cannot fit its node baseline")
            roles.append(
                {
                    **wire.model_dump(),
                    "input_tokens": baseline - output,
                    "output_tokens": output,
                    "max_steps": steps,
                    "max_tool_calls": calls if wire.tools else 0,
                    "max_duration_seconds": duration_by_key[wire.task_node_key],
                    "depth": node_depth(graph, wire.task_node_key),
                }
            )
        allocation = sum(nodes[key]["budget_tokens"] for key in keys) + (
            serial["shared_reserve_tokens"] if serial else 0
        )
        if allocation > min(
            graph["max_total_tokens"] - (graph.get("coordination_reserve_tokens") or 0),
            maximum.get("max_total_tokens", graph["max_total_tokens"]),
        ):
            raise DomainError("Core team resources exceed the original approved ceiling")
        tools = sorted({tool for role in self.roles for tool in role.tools})
        limits = {
            "max_members": count,
            "max_depth": max(role["depth"] for role in roles),
            "max_concurrency": concurrency,
            "max_total_tokens": allocation,
            "max_total_tool_calls": sum(role["max_tool_calls"] for role in roles),
            "max_cost_microunits": graph.get("max_cost_microunits"),
            "currency": graph.get("cost_currency"),
            "allowed_tools": tools,
        }
        # The unchanged legacy parser supplies all established role validators,
        # including explicit-null strict schema selection for dynamic roles.
        return TeamWire.model_validate(
            {"roles": roles, "limits": limits, "strategy": self.strategy}
        ).inputs()


_DIAGNOSTIC_FIELDS = frozenset(
    {
        "roles",
        "id",
        "task_node_key",
        "required_capabilities",
        "name",
        "minimum",
        "tools",
        "dynamic",
        "responsibility",
        "input_contract",
        "output_schema_json",
        "acceptance_criteria",
        "strategy",
        "limits",
        "input_tokens",
        "output_tokens",
        "max_steps",
        "max_tool_calls",
        "max_duration_seconds",
        "depth",
        "max_members",
        "max_depth",
        "max_concurrency",
        "max_total_tokens",
        "max_total_tool_calls",
        "max_cost_microunits",
        "currency",
        "allowed_tools",
    }
)
_CAPACITY_NUMBERS = frozenset(
    {
        "known_source_bytes",
        "future_source_bytes_bound",
        "raw_packet_bytes",
        "growth_bound",
        "raw_packet_bound",
        "raw_packet_limit",
        "review_input_bound",
        "correction_input_bound",
        "worker_input_bound",
        "model_context_limit",
        "output_bound",
        "allocated_tokens",
        "minimum_node_tokens",
        "review_correction_reserve",
        "initial_work_tokens",
        "baseline_tokens",
    }
)


def safe_team_rejection_diagnostics(exc=None):
    """No model text, input values, exception messages, or raw schemas are stored."""
    result = {"kind": "incomplete_team_proposal" if exc is None else "invalid_team_proposal"}
    errors = getattr(exc, "errors", None)
    if callable(errors):
        result["fields"] = [
            [
                part
                if type(part) is int and 0 <= part <= 127
                else part
                if isinstance(part, str) and part in _DIAGNOSTIC_FIELDS
                else "unrecognized_field"
                for part in error.get("loc", ())[:8]
            ]
            for error in errors()[:8]
        ]
    capacity = getattr(exc, "capacity_diagnostics", None)
    if isinstance(capacity, dict):
        result["capacity"] = {
            key: value
            for key, value in capacity.items()
            if key in _CAPACITY_NUMBERS and type(value) is int and 0 <= value <= 1000000000
        }
    return result

