    if callable(errors):
        known_reasons = {
            _safe_rejection_reason(error.get("ctx", {}).get("error", "")) for error in errors()[:8]
        } - {"unclassified_rejection"}
        if known_reasons:
            result["validation_reasons"] = sorted(known_reasons)
        result["fields"] = [
