                        "outcome": "success"
                        if status == "ok"
                        else "timeout"
                        if status == "timeout"
                        else "error",
                        "latency_seconds": self._health["latency_seconds"],
                        "ttft_seconds": ttft,
                        "output_tokens": (usage or {}).get("output_tokens"),
                    },
                )
