"""Final artifact audit with explicit Core-source and supplementary goal gates.

This builder imports no FORGE code, opens no runtime database, and never starts a
Provider. It reads new independent usage/supplementary audits, not verified flags
from a live driver. Historical independent auditor bytes remain unchanged.
"""

import argparse
import hashlib
import importlib.util
import json
import re
import types
from datetime import UTC, datetime
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
AUDIT = REPO / "docs/audit/phase2"
BASELINE = "3da6d6293045489173e9fcb6d17d59b249515ea39929d73cfe41fb68757c60ef"
CORE_POLICY = "core-declared-source-prefetch-v1"
SUPPLEMENT_MODES = {7: "parallel", 9: "controlled-defect", 11: "review-revision"}
MEMORY_AUDITOR_SHA256 = "PENDING_V29_MEMORY_AUDITOR_HASH"
CORE_AUDITOR_SHA256 = "PENDING_V29_CORE_AUDITOR_HASH"


def canonical(value):
    return json.dumps(
        value,
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    ).encode()


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def strict_json(raw):
    def pairs(items):
        value = {}
        for key, item in items:
            if key in value:
                raise ValueError("Duplicate JSON key")
            value[key] = item
        return value

    def reject(_value):
        raise ValueError("Nonfinite JSON")

    return json.loads(raw, object_pairs_hook=pairs, parse_constant=reject)


def read(path):
    return strict_json(Path(path).read_bytes())


def evidence(path):
    path = Path(path).resolve()
    raw = path.read_bytes()
    return {
        "path": path.relative_to(REPO).as_posix(),
        "bytes": len(raw),
        "sha256": sha(raw),
    }


def bound_reference(ref):
    if not isinstance(ref, dict) or set(ref) != {"path", "bytes", "sha256"}:
        return False
    path = (REPO / ref["path"]).resolve()
    return path.is_relative_to(REPO) and path.is_file() and evidence(path) == ref


def core_checks(report):
    """Consume an independently reconstructed SQL audit; zero rows are vacuous."""
    errors = []
    core = report.get("core_declared_source_audit")
    if not isinstance(core, dict):
        return ["independent_core_source_audit_missing"]
    for field in ("source_evidence_checks_passed", "tool_accounting_checks_passed"):
        if core.get(field) is not True:
            errors.append(field)
    if core.get("errors") or core.get("orphan_admission_event_ids"):
        errors.append("core_source_errors_or_orphans")
    sources, inventories = core.get("sources", []), core.get("worker_inventories", [])
    if core.get("source_count") != len(sources):
        errors.append("core_source_inventory_length")
    if any(
        row.get("origin") != CORE_POLICY
        or not row.get("approved_assignment_valid")
        or not row.get("admission_inventory_complete")
        or row.get("declared_source_count") != row.get("admitted_source_count")
        for row in inventories
    ):
        errors.append("core_approved_source_inventory")
    required = (
        "admission_binding_valid",
        "settled_source_valid",
        "no_model_reservation_or_gateway_attempt",
        "complete_user_message_valid",
        "user_message_precedes_first_assistant",
    )
    if any(
        row.get("origin") != CORE_POLICY
        or any(row.get(field) is not True for field in required)
        for row in sources
    ):
        errors.append("core_full_source_evidence")
    counters = report.get("worker_counters", core.get("tool_counters", []))
    if any(
        row.get("tools_exact") is not True
        or row.get("model_selection_bindings_valid") is not True
        or row.get("unattributed_tool_spend") != 0
        for row in counters
    ):
        errors.append("exact_model_and_core_tool_accounting")
    for row in sources:
        if row.get("tool_name") == "worker_read_completed_delivery" and (
            row.get("receipt_id") is not None
            or not row.get("producer_original_live_evidence_valid")
            or not row.get("producer_reconstructed_review_passes")
            or not all(row["producer_reconstructed_review_passes"].values())
        ):
            errors.append("core_original_predecessor_proof")
    return errors


def usage_extension(path, frozen):
    report = read(path)
    errors = []
    if report.get("audit_version", 0) < 2 or not report.get(
        "baseline_auditor_preserved"
    ):
        errors.append("new_independent_usage_auditor_required")
    if report.get("audit_script_sha256") != CORE_AUDITOR_SHA256:
        errors.append("usage_auditor_identity_mismatch")
    for run in report.get("runs", []):
        if (
            run.get("token_budgets_enforced") is not False
            or run.get("gateway_tokens_within_original_scenario_limit") is not None
        ):
            errors.append(f"{run['run_id']}:explicit_disabled_token_protocol")
        if (
            run.get("all_gateway_usage_known_and_settled") is not True
            or run.get("opening_usage_valid") is not True
            or run.get("opening_usage") != []
        ):
            errors.append(f"{run['run_id']}:settled_usage_and_fresh_opening")
        if run.get("context_archive_integrity", {}).get("passed") is not True:
            errors.append(f"{run['run_id']}:archive_integrity")
        for error in core_checks(run):
            errors.append(f"{run['run_id']}:{error}")
        if run.get("source_mismatches") or not run.get("frozen_manifest_match"):
            errors.append(f"{run['run_id']}:snapshot_manifest")
        if (
            run.get("driver_code_snapshot_sha256")
            != frozen["executable_snapshot_sha256"]
        ):
            errors.append(f"{run['run_id']}:executable_snapshot")
        for proof in run.get("reconstructed_review_passes", []):
            if "reconstruction_error_type" in proof:
                errors.append(f"{run['run_id']}:review_reconstruction")
            if proof.get("raw_packet_bytes", 65537) > 65536:
                errors.append(f"{run['run_id']}:raw_packet_cap")
        if any(
            not row.get("original_live_evidence_valid")
            for row in run.get("succeeded_node_live_evidence_revalidation", [])
        ):
            errors.append(f"{run['run_id']}:current_node_provenance")
    return {
        "evidence": evidence(path),
        "errors": errors,
        "passed": not errors,
        "source_rows": sum(
            run["core_declared_source_audit"]["source_count"]
            for run in report.get("runs", [])
        ),
        "zero_rows_do_not_prove_prefetch": True,
    }


def supplements(index_path, frozen):
    if index_path is None:
        return {
            "evidence": None,
            "modes": {},
            "passed": False,
            "reason": "supplementary_actual_evidence_missing",
        }
    index = read(index_path)
    modes = {}
    for ref in index.get("independent_audits", []):
        if not bound_reference(ref):
            raise ValueError("Supplementary independent audit reference mismatch")
        row = read(REPO / ref["path"])
        mode = row.get("mode")
        errors = []
        if mode not in SUPPLEMENT_MODES.values() or mode in modes:
            raise ValueError("Unknown/duplicate supplementary mode")
        for key in (
            "driver_record",
            "original_spec",
            "saved_evidence",
            "goal_auditor",
            "core_auditor",
        ):
            if not bound_reference(row.get(key)):
                errors.append("unbound_" + key)
        if (
            row.get("source_version") != frozen["source_version"]
            or row.get("frozen_manifest_sha256") != frozen["manifest_sha256"]
            or row.get("frozen_executable_sha256")
            != frozen["executable_snapshot_sha256"]
        ):
            errors.append("supplementary_frozen_identity")
        if row.get("read_snapshot_total_changes") != 0:
            errors.append("supplementary_readonly")
        for field in (
            "original_spec_matches",
            "code_snapshots_match",
            "driver_snapshots_match",
            "saved_evidence_matches_recollection",
            "independent_passes_reconstructed",
            "known_settled_usage_and_other_limits",
            "fresh_workspace_no_opening_usage",
            "cumulative_token_budget_explicitly_disabled",
            "goal_exchange_bindings_valid",
        ):
            if row.get(field) is not True:
                errors.append(field)
        errors.extend(core_checks(row))
        result = row.get("goal_audit", {})
        if (
            result.get("passed") is not True
