    errors = wrapper.validate_report(row, frozen, bound_reference)
    if row.get("independent_auditor") != evidence(wrapper_path):
        errors.append("memory_independent_auditor_identity")
    errors.extend(core_checks(row))
    return {
        "evidence": evidence(path),
        "passed": not errors,
        "errors": errors,
        "claim_boundary": "One controlled completed cross-Quest reuse sample; lexical/semantic/compacted-context contributions are not causally separated. Historical retrieval alone is insufficient.",
    }


def goals_from_draft(draft, live, supplementary, memory_result, source_version):
    """Keep every requirement; promotion requires concrete immutable evidence."""
    original = draft["goals"]
    if len(original) != 15 or {row["number"] for row in original} != set(range(1, 16)):
        raise ValueError("Original 15-goal inventory missing")
    observed_checks = {
        name
        for row in live["current_source_runs"]
        if row["strictly_accepted"]
        for name, status in row["acceptance"].get("checks", {}).items()
        if status == "passed"
    }
    goals = []
    for item in original:
        row = dict(item)
        required = set(item.get("required_strict_checks", []))
        strict = live["all_three_levels_accepted"] and required <= observed_checks
        if item["number"] in SUPPLEMENT_MODES:
            mode = SUPPLEMENT_MODES[item["number"]]
            accepted = supplementary["modes"].get(mode, {}).get("passed") is True
            observation = supplementary["modes"].get(
                mode,
                {"passed": False, "reason": "actual_supplementary_evidence_missing"},
            )
        elif item["number"] == 13:
            accepted, observation = memory_result["passed"], memory_result
        else:
            accepted, observation = (
                strict,
                {
                    "all_three_strict_levels_accepted": live[
                        "all_three_levels_accepted"
                    ],
                    "required_checks_missing_from_accepted_runs": sorted(
                        required - observed_checks
                    ),
                },
            )
        row.update(
            source_version=source_version,
            acceptance_status="satisfied" if accepted else "not_demonstrated",
            independent_observation=observation,
        )
        goals.append(row)
    return goals


def live_usage_v29(path, frozen, live):
    """Artifact-only reconciliation for the explicit changed token protocol."""
    report = read(path)
    snapshots = {row["run_id"]: row for row in live["current_source_runs"]}
    errors, known = [], 0
    if (
        report.get("source_version") != frozen["source_version"]
        or report.get("frozen_manifest_sha256") != frozen["manifest_sha256"]
        or report.get("frozen_manifest_file_sha256") != frozen["manifest"]["sha256"]
        or report.get("current_frozen_source_mismatches")
    ):
        errors.append("usage_frozen_source_identity")
    for row in report.get("runs", []):
        run_id = row["run_id"]
        if not bound_reference(
            {
                "path": row["driver_record_path"],
                "bytes": (REPO / row["driver_record_path"]).stat().st_size,
                "sha256": row["driver_record_sha256"],
            }
        ):
            errors.append("driver_record_identity:" + run_id)
        for flag in (
            "accounting_checks_passed",
            "driver_usage_matches_database",
            "unknown_or_sent_reservations_never_refunded",
            "all_gateway_usage_known_and_settled",
            "opening_usage_valid",
        ):
            if row.get(flag) is not True:
                errors.append(flag + ":" + run_id)
        if (
            row.get("read_snapshot_total_changes") != 0
            or row.get("opening_usage") != []
            or row.get("driver_code_snapshot_sha256")
            != frozen["executable_snapshot_sha256"]
            or row.get("held_allocation_audit", {}).get("passed") is not True
        ):
            errors.append("usage_assignment_or_snapshot:" + run_id)
        if (
            row.get("token_budgets_enforced") is not False
            or row.get("gateway_tokens_within_original_scenario_limit") is not None
        ):
            errors.append("explicit_disabled_token_protocol:" + run_id)
        if row.get("missing_gateway_usage_count") != 0:
            errors.append("unknown_model_attempt:" + run_id)
        if any(
            item.get("receipt_hash_matches") is not True
            for item in row.get("artifact_hash_checks", [])
        ) or any(
            item.get("original_live_evidence_valid") is not True
            for item in row.get("succeeded_node_live_evidence_revalidation", [])
        ):
            errors.append("current_artifact_and_node_proof:" + run_id)
        snapshot = snapshots.get(run_id)
        if (
            snapshot is None
            or row.get("acceptance_passed") != snapshot["acceptance"].get("passed")
            or sum(
                (snapshot.get("token_usage") or {}).get(key, 0)
                for key in ("input", "output")
            )
            != row["known_gateway_tokens"]
        ):
            errors.append("published_snapshot_binding:" + run_id)
        known += row["known_gateway_tokens"]
    if {row["run_id"] for row in report.get("runs", [])} != set(snapshots):
        errors.append("usage_run_inventory")
    return {
        "evidence": evidence(path),
        "runs": len(report.get("runs", [])),
        "known_tokens": known,
        "consistency_errors": errors,
        "passed": not errors,
        "token_budget_protocol": "disabled_by_user; no replacement cumulative cap; all usage must be known and settled",
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--version", required=True)
    parser.add_argument("--freeze-path", type=Path, required=True)
    parser.add_argument("--study", type=Path, required=True)
    parser.add_argument("--study-source-manifest", type=Path, required=True)
