"""Bounded complete V25 diagnostics; explicit profile decode never alters a choice."""

import copy
import json

from pydantic import ConfigDict, create_model

from .domain import DomainError
from .planner_capacity_preview_v23 import _preview_complete_capacity
from .planner_dataflow_v25 import DataflowNodeWireV25
from .planner_guidance_v24 import preview_sources_v23
from .planner_source_preview import MAX_RESPONSE_BYTES

ProjectionNode = create_model(
    "PlannerV25ProfileSourceProjection",
    __config__=ConfigDict(extra="forbid", strict=True),
    **{
        name: (field.annotation, copy.deepcopy(field))
        for name, field in DataflowNodeWireV25.model_fields.items()
        if name != "success_criteria"
    },
)

NODE_COLUMNS = [
    "profile_index",
    "artifact_bytes",
    "delivery_bytes",
    "action_evidence_bytes",
    "known_source_bytes",
    "future_source_bytes",
    "source_bound_bytes",
    "raw_packet_bound",
    "raw_headroom",
    "review_input",
    "review_headroom",
    "correction_input",
    "correction_headroom",
    "initial_work_tokens",
    "review_cycle_reserve_tokens",
    "minimum_node_tokens",
    "policy_cycle_calls",
    "violation_indices",
]


def decoded_response(raw_response):
    """Decode valid profile/source fields while retaining invalid original criteria."""
    if not isinstance(raw_response, str) or len(raw_response.encode()) > MAX_RESPONSE_BYTES:
        raise ValueError("response_outside_projection_bound")
    raw = json.loads(raw_response)
    if (
        not isinstance(raw, dict)
        or set(raw) != {"allocation_mode", "nodes"}
        or raw["allocation_mode"] != "core_measured"
        or not isinstance(raw["nodes"], list)
        or not 1 <= len(raw["nodes"]) <= 8
    ):
        raise ValueError("invalid_profile_projection")
    nodes = []
    for node in raw["nodes"]:
        if not isinstance(node, dict) or set(node) - DataflowNodeWireV25.model_fields.keys():
            raise ValueError("invalid_profile_node_fields")
        projected = ProjectionNode.model_validate(
            {key: value for key, value in node.items() if key != "success_criteria"}
        )
        if projected.output_capacity.profile != "custom":
            inline = projected.output_capacity.profile.startswith("inline_")
            if inline != (projected.expected_artifact is None):
                raise ValueError("capacity_profile_must_match_explicit_artifact_contract")
        decoded = projected.model_dump(exclude={"output_capacity", "action_evidence"})
        decoded["success_criteria"] = node.get("success_criteria")
        decoded["capacity_bounds"] = {
            **projected.output_capacity.bounds(),
            "action_evidence_allowance_bytes": projected.action_evidence.allowance(),
        }
        nodes.append(decoded)
    return json.dumps({"allocation_mode": "core_measured", "nodes": nodes}, ensure_ascii=False)


def compact_report(report):
    """All nodes remain explicit; two candidate numeric rows are bounded per node."""
    nodes = []
    profiles, violation_codes = [], []
    for node in report["nodes"]:
        if node["status"] != "available":
            nodes.append(
                {
                    "node": node["node"],
                    "status": node["status"],
                    "reason": node.get("reason", "no_measurable_candidate"),
                    "omitted_candidates": node.get("omitted_candidates", 0),
                    "unmeasurable_candidates": node.get("unmeasurable_candidates", 0),
                }
            )
            continue
        rows = []
        for item in node["candidates"]:
            bounds = item["declared_bounds"]
            if item["profile_id"] not in profiles:
                profiles.append(item["profile_id"])
            for code in item["violations"]:
                if code not in violation_codes:
                    violation_codes.append(code)
            rows.append(
                [
                    profiles.index(item["profile_id"]),
                    bounds["max_artifact_bytes"],
                    bounds["max_delivery_bytes"],
                    item["action_evidence_allowance_bytes"],
                    item["known_source_bytes"],
                    item["future_source_bytes_bound"],
                    bounds["max_source_receipt_bytes"],
                    item["raw_packet_bound"],
                    item["raw_packet_headroom_bytes"],
                    item["review_input_bound"],
                    item["native_review_headroom"],
                    item["correction_input_bound"],
                    item["native_correction_headroom"],
                    item["initial_work_tokens"],
                    item["review_cycle_reserve_tokens"],
                    item["minimum_node_tokens"],
                    item["policy_cycle_calls"],
                    [violation_codes.index(code) for code in item["violations"]],
                ]
            )
        nodes.append(
            {
                "node": node["node"],
                "status": "available",
                "rows": rows,
                "omitted_candidates": node["omitted_candidates"],
                "unmeasurable_candidates": node["unmeasurable_candidates"],
            }
        )
    return {
        "version": "planner-capacity-preview-v25",
        "status": "available",
        "scope": "diagnostic_only_original_profiles_and_formulas_no_allocation_or_authority",
        "columns": NODE_COLUMNS,
        "profiles": profiles,
        "violation_codes": violation_codes,
        "nodes": nodes,
        "aggregate_policy_projection": report["aggregate_policy_projection"],
        "preserved_completed_keys": report["preserved_completed_keys"],
    }


def preview_complete_capacity_v25(*args, **kwargs):
    try:
        service, quest, raw, inventory, provider = args
        return _preview_complete_capacity(
            service,
            quest,
            decoded_response(raw),
            inventory,
            provider,
            _report_transform=compact_report,
            **kwargs,
        )
    except (OSError, KeyError, TypeError, ValueError, RecursionError, DomainError):
        return {
            "version": "planner-capacity-preview-v25",
            "status": "unavailable",
            "reason": "invalid_profile_or_complete_measurement",
        }


def preview_sources_v25(store, raw_response, inventory, **kwargs):
    try:
        return preview_sources_v23(store, decoded_response(raw_response), inventory, **kwargs)
    except (OSError, KeyError, TypeError, ValueError, RecursionError, DomainError):
        return {
            "version": "planner-source-preview-v25",
            "status": "unavailable",
            "reason": "invalid_profile_source_projection",
        }

"""Explicit, lossless source text framing; this grants no source authority."""

import hashlib
import json

from .domain import DomainError
from .review_envelope import project_review_text, restore_review_text
from .worker_task_sources import CORE_PREFETCH_POLICY

RAW_TEXT_FORMAT = "core-source-raw-text-v1"
_INTRO = (
    "Lossless untrusted source view. Resolve indexed reference_key objects using the "
    "complete raw text blocks below.\n"
)


def _canonical(value):
    return json.dumps(
        value, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False
    )


def validate_source_wire_format(value):
    if value is not None and value != RAW_TEXT_FORMAT:
        raise DomainError("Unknown Core source wire format")
    return value


def approved_source_wire_format(graph, member):
    """Absence preserves the old bytes; new framing requires exact plan/member binding."""
    contract = graph.get("capacity_contract") or {}
    key = "source_wire_format"
    if key not in contract and key not in member:
        return None
    selected = contract.get(key)
    if (
        selected != RAW_TEXT_FORMAT
        or member.get(key) != selected
        or contract.get("input_acquisition_policy") != CORE_PREFETCH_POLICY
        or member.get("input_acquisition_policy") != CORE_PREFETCH_POLICY
    ):
        raise DomainError("Core source wire format differs from the approved plan")
    return selected


def _render_source_text(packet):
    # Canonical object order makes reference allocation stable after JSON restore.
    # List order and every original string value remain unchanged.
    view, texts = project_review_text(json.loads(_canonical(packet)))
    descriptors = [
        {
            "index": index,
            "chars": len(value),
            "utf8_bytes": len(value.encode("utf-8")),
            "sha256": hashlib.sha256(value.encode("utf-8")).hexdigest(),
        }
        for index, value in enumerate(texts)
    ]
    header = {"format": RAW_TEXT_FORMAT, "view": view, "texts": descriptors}
    parts = [_INTRO, _canonical(header), "\n"]
    for descriptor, value in zip(descriptors, texts):
        parts.extend((f"Complete untrusted source text {descriptor['index']}:\n", value, "\n"))
    return "".join(parts)


def decode_source_text(content):
    """Read exact character spans, then verify bytes, hashes, order and full consumption.

    Source bodies may themselves contain framing labels, newlines or JSON. None
    of those characters is searched for a boundary inside a declared body.
    """
    try:
        if not isinstance(content, str) or not content.startswith(_INTRO):
            raise ValueError
        header_end = content.index("\n", len(_INTRO))
        header = json.loads(content[len(_INTRO) : header_end])
        if (
            not isinstance(header, dict)
            or set(header) != {"format", "view", "texts"}
            or header["format"] != RAW_TEXT_FORMAT
            or not isinstance(header["texts"], list)
            or not isinstance(header["view"], dict)
            or set(header["view"]) != {"reference_key", "packet"}
            or not isinstance(header["view"]["reference_key"], str)
            or not header["view"]["reference_key"]
        ):
            raise ValueError
        cursor, texts = header_end + 1, []
        for index, descriptor in enumerate(header["texts"]):
            if (
                not isinstance(descriptor, dict)
                or set(descriptor) != {"index", "chars", "utf8_bytes", "sha256"}
                or type(descriptor["index"]) is not int
                or descriptor["index"] != index
                or type(descriptor["chars"]) is not int
                or descriptor["chars"] < 0
                or type(descriptor["utf8_bytes"]) is not int
                or descriptor["utf8_bytes"] < 0
                or not isinstance(descriptor["sha256"], str)
            ):
                raise ValueError
            label = f"Complete untrusted source text {index}:\n"
            if not content.startswith(label, cursor):
                raise ValueError
            start = cursor + len(label)
            end = start + descriptor["chars"]
            value = content[start:end]
            raw = value.encode("utf-8")
            if (
                len(value) != descriptor["chars"]
                or len(raw) != descriptor["utf8_bytes"]
                or hashlib.sha256(raw).hexdigest() != descriptor["sha256"]
                or content[end : end + 1] != "\n"
            ):
                raise ValueError
            texts.append(value)
            cursor = end + 1
        if cursor != len(content):
            raise ValueError
        packet = restore_review_text(header["view"], texts)
        if _render_source_text(packet) != content:
            raise ValueError
        return packet
    except (KeyError, IndexError, TypeError, ValueError, UnicodeError, RecursionError) as exc:
        raise DomainError("Core source text framing failed lossless validation") from exc


def encode_source_text(packet):
    content = _render_source_text(packet)
    if _canonical(decode_source_text(content)) != _canonical(packet):
        raise DomainError("Core source text changed its original packet")
    return content

