def usage_extension(path, frozen):
    report = read(path)
    errors = []
    if report.get("audit_version", 0) < 2 or not report.get(
        "baseline_auditor_preserved"
    ):
        errors.append("new_independent_usage_auditor_required")
    if (
        not re.fullmatch("[0-9a-f]{64}", CORE_AUDITOR_SHA256)
        or report.get("audit_script_sha256") != CORE_AUDITOR_SHA256
    ):
        errors.append("usage_auditor_identity_mismatch")
    for run in report.get("runs", []):
        if (
            run.get("token_budgets_enforced") is not False
            or run.get("gateway_tokens_within_original_scenario_limit") is not None
        ):
            errors.append(f"{run['run_id']}:explicit_disabled_token_protocol")
        if (
            run.get("all_gateway_usage_known_and_settled") is not True
            or run.get("opening_usage_valid") is not True
            or run.get("opening_usage") != []
        ):
            errors.append(f"{run['run_id']}:settled_usage_and_fresh_opening")
        if run.get("context_archive_integrity", {}).get("passed") is not True:
            errors.append(f"{run['run_id']}:archive_integrity")
        if (
            run.get("model_compaction_checkpoints", {}).get("applicable") is True
            and run["model_compaction_checkpoints"].get("passed") is not True
        ):
            errors.append(f"{run['run_id']}:model_compaction_checkpoint")
        for error in core_checks(run):
            errors.append(f"{run['run_id']}:{error}")
        if run.get("source_mismatches") or not run.get("frozen_manifest_match"):
            errors.append(f"{run['run_id']}:snapshot_manifest")
        if (
            run.get("driver_code_snapshot_sha256")
            != frozen["executable_snapshot_sha256"]
        ):
            errors.append(f"{run['run_id']}:executable_snapshot")
        for proof in run.get("reconstructed_review_passes", []):
            if "reconstruction_error_type" in proof:
                errors.append(f"{run['run_id']}:review_reconstruction")
            if proof.get("raw_packet_bytes", 65537) > 65536:
                errors.append(f"{run['run_id']}:raw_packet_cap")
        if any(
            not row.get("original_live_evidence_valid")
            for row in run.get("succeeded_node_live_evidence_revalidation", [])
        ):
            errors.append(f"{run['run_id']}:current_node_provenance")
    return {
        "evidence": evidence(path),
        "errors": errors,
        "passed": not errors,
        "source_rows": sum(
            run["core_declared_source_audit"]["source_count"]
            for run in report.get("runs", [])
        ),
        "zero_rows_do_not_prove_prefetch": True,
    }


def supplements(index_path, frozen):
    if index_path is None:
        return {
            "evidence": None,
            "modes": {},
            "passed": False,
            "reason": "supplementary_actual_evidence_missing",
        }
    index = read(index_path)
    modes = {}
    for ref in index.get("independent_audits", []):
        if not bound_reference(ref):
            raise ValueError("Supplementary independent audit reference mismatch")
        row = read(REPO / ref["path"])
        mode = row.get("mode")
        errors = []
        if row.get("schema") != "independent-supplementary-goal-v29-no-token-budget-1":
            errors.append("supplementary_protocol_schema")
        for field, filename, digest in (
            (
                "independent_auditor",
                "audit_supplement_v29.py",
                SUPPLEMENT_AUDITOR_SHA256,
            ),
            ("core_auditor", "audit_live_usage_v29.py", CORE_AUDITOR_SHA256),
        ):
            if (
                not re.fullmatch("[0-9a-f]{64}", digest)
                or row.get(field) != evidence(Path(__file__).with_name(filename))
                or row[field]["sha256"] != digest
            ):
                errors.append("supplementary_auditor_identity:" + field)
        goal_ref = row.get("goal_auditor", {})
        if (
            not re.fullmatch("[0-9a-f]{64}", GOAL_AUDITOR_SHA256)
            or goal_ref.get("sha256") != GOAL_AUDITOR_SHA256
        ):
            errors.append("goal_auditor_identity")
        if mode not in SUPPLEMENT_MODES.values() or mode in modes:
            raise ValueError("Unknown/duplicate supplementary mode")
        for key in (
            "driver_record",
            "original_spec",
            "saved_evidence",
            "goal_auditor",

                "correction_attempt_id",
                "needs_revision_model_attempt_id",
                "pass_model_attempt_id",
            ),
        }
        if any(
            not isinstance(proof.get(field), str) or not proof[field]
            for field in required_goal_fields[mode]
        ):
            errors.append("actual_goal_exchange_identifiers_missing")
        if mode == "controlled-defect" and (
            proof.get("original_sha256") == proof.get("revised_sha256")
            or len(set(proof.get("model_attempt_ids", []))) != 3
        ):
            errors.append("distinct_failure_revision_retest_required")
        if mode == "review-revision" and (
            proof.get("initial_result_event_id") == proof.get("final_result_event_id")
            or proof.get("needs_revision_model_attempt_id")
            == proof.get("pass_model_attempt_id")
        ):
            errors.append("distinct_revision_and_fresh_review_required")
        if mode == "parallel" and (
            type(proof.get("sample_index")) is not int
            or len(proof.get("sample", {}).get("attempts", [])) < 2
        ):
            errors.append("actual_parallel_attempt_overlap_missing")
        if (
            row.get("passed") is not True
            or row.get("unknown_attempt_ids")
            or row.get("opening_usage") != []
            or row.get("held_allocation_audit", {}).get("passed") is not True
            or not row.get("reconstructed_passes")
            or not all(
                item.get("passed") is True for item in row["reconstructed_passes"]
            )
        ):
            errors.append("independent_assignment_usage_and_current_pass_required")
        if (
            result.get("passed") is not True
            or result.get("failures")
            or result.get("goal_evidence", {}).get("passed") is not True
        ):
            errors.append("actual_goal_not_passed")
        if (
            result.get("usage", {}).get("unknown_attempt_ids")
            or result.get("receipt_failures")
            or any(
                item.get("unchanged") is not True
                for item in result.get("input_checks", [])
            )
        ):
            errors.append("supplementary_unresolved_or_changed_sources")
        if mode == "parallel" and not bound_reference(row.get("reservation_samples")):
            errors.append("parallel_actual_overlap_samples_missing")
        if row.get("finished_driver_passed") is not True or row.get(
            "finished_driver_failures"
        ):
            errors.append("original_driver_failed")
        modes[mode] = {
            "evidence": ref,
            "passed": not errors,
            "errors": errors,
            "goal_evidence": result.get("goal_evidence", {}),
            "claim_boundary": row.get("claim_boundary"),
        }
    return {
        "evidence": evidence(index_path),
        "modes": modes,
        "passed": set(modes) == set(SUPPLEMENT_MODES.values())
        and all(row["passed"] for row in modes.values()),
    }


def memory(path, frozen):
    if path is None:
        return {
            "evidence": None,
            "passed": False,
            "reason": "completed_crossquest_reuse_not_observed",
        }
    row = read(path)
    wrapper_path = Path(__file__).with_name("audit_memory_v29.py")
    if sha(wrapper_path.read_bytes()) != MEMORY_AUDITOR_SHA256:
        raise ValueError("Pinned independent memory auditor changed")
    spec = importlib.util.spec_from_file_location(
        "artifact_only_memory_gate", wrapper_path
    )
    wrapper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(wrapper)
    errors = wrapper.validate_report(row, frozen, bound_reference)
    if row.get("independent_auditor") != evidence(wrapper_path):
        errors.append("memory_independent_auditor_identity")
    errors.extend(core_checks(row))
    return {
        "evidence": evidence(path),
        "passed": not errors,
        "errors": errors,
        "claim_boundary": "One controlled completed cross-Quest reuse sample; lexical/semantic/compacted-context contributions are not causally separated. Historical retrieval alone is insufficient.",
    }


def goals_from_draft(draft, live, supplementary, memory_result, source_version):
    """Keep every requirement; promotion requires concrete immutable evidence."""
    original = draft["goals"]
    if len(original) != 15 or {row["number"] for row in original} != set(range(1, 16)):
        raise ValueError("Original 15-goal inventory missing")
    observed_checks = {
        name
        for row in live["current_source_runs"]
        if row["strictly_accepted"]
        for name, status in row["acceptance"].get("checks", {}).items()
        if status == "passed"
    }
    goals = []
    for item in original:
        row = dict(item)
        required = set(item.get("required_strict_checks", []))
        strict = live["all_three_levels_accepted"] and required <= observed_checks
        if item["number"] in SUPPLEMENT_MODES:
            mode = SUPPLEMENT_MODES[item["number"]]
            accepted = (
                strict and supplementary["modes"].get(mode, {}).get("passed") is True
            )
            observation = supplementary["modes"].get(
                mode,
                {"passed": False, "reason": "actual_supplementary_evidence_missing"},
            )
        elif item["number"] == 13:
            accepted, observation = strict and memory_result["passed"], memory_result
        elif item["number"] in {12, 14}:
            field = (
                "compaction_followed_by_actual_execution_and_completion"
                if item["number"] == 12
                else "mid_execution_process_restart_and_continuation"
            )
            qualifying = [
                source
                for source in live["current_source_runs"]
                if source.get("strictly_accepted") is True
                and required
                <= {
                    name
                    for name, status in source.get("acceptance", {})
                    .get("checks", {})
                    .items()
