"""Offline counterexamples for the final V29 artifact gates; no Provider or SQL."""

import copy
import importlib.util
import json
from pathlib import Path

import pytest

spec = importlib.util.spec_from_file_location(
    "final_audit_v29", Path(__file__).with_name("audit_final_v29.py")
)
audit = importlib.util.module_from_spec(spec)
spec.loader.exec_module(audit)


def write_json(path, value):
    path.write_text(json.dumps(value, allow_nan=False), encoding="utf-8")
    return path


def valid_core():
    return {
        "core_declared_source_audit": {
            "source_evidence_checks_passed": True,
            "tool_accounting_checks_passed": True,
            "source_count": 1,
            "sources": [
                {
                    "origin": audit.CORE_POLICY,
                    "tool_name": "file_read",
                    "admission_binding_valid": True,
                    "settled_source_valid": True,
                    "no_model_reservation_or_gateway_attempt": True,
                    "complete_user_message_valid": True,
                    "user_message_precedes_first_assistant": True,
                }
            ],
            "worker_inventories": [
                {
                    "origin": audit.CORE_POLICY,
                    "approved_assignment_valid": True,
                    "admission_inventory_complete": True,
                    "declared_source_count": 1,
                    "admitted_source_count": 1,
                }
            ],
            "tool_counters": [
                {
                    "tools_exact": True,
                    "model_selection_bindings_valid": True,
                    "unattributed_tool_spend": 0,
                }
            ],
        }
    }


def frozen():
    return {
        "source_version": "v29",
        "manifest_sha256": "a" * 64,
        "manifest": {"sha256": "b" * 64},
        "executable_snapshot_sha256": "c" * 64,
    }


def usage_fixture(tmp_path, monkeypatch):
    monkeypatch.setattr(audit, "REPO", tmp_path)
    monkeypatch.setattr(
        audit,
        "CORE_AUDITOR_SHA256",
        audit.sha(Path(__file__).with_name("audit_live_usage_v29.py").read_bytes()),
    )
    selected = frozen()
    driver = write_json(tmp_path / "driver.json", {"run_id": "actual-run"})
    row = {
        **valid_core(),
        "run_id": "actual-run",
        "driver_record_path": driver.name,
        "driver_record_sha256": audit.sha(driver.read_bytes()),
        "driver_code_snapshot_sha256": selected["executable_snapshot_sha256"],
        "read_snapshot_total_changes": 0,
        "opening_usage": [],
        "token_budgets_enforced": False,
        "gateway_tokens_within_original_scenario_limit": None,
        "missing_gateway_usage_count": 0,
        "known_gateway_tokens": 20,
        "accounting_checks_passed": True,
        "driver_usage_matches_database": True,
        "unknown_or_sent_reservations_never_refunded": True,
        "all_gateway_usage_known_and_settled": True,
        "opening_usage_valid": True,
        "held_allocation_audit": {"passed": True},
        "context_archive_integrity": {"passed": True},
        "frozen_manifest_match": True,
        "source_mismatches": [],
        "artifact_hash_checks": [{"receipt_hash_matches": True}],
        "succeeded_node_live_evidence_revalidation": [
            {"original_live_evidence_valid": True}
        ],
        "reconstructed_review_passes": [{"raw_packet_bytes": 100}],
        "acceptance_passed": True,
    }
    report = {
        "audit_version": 2,
        "audit_script_sha256": audit.CORE_AUDITOR_SHA256,
        "baseline_auditor_preserved": True,
        "source_version": selected["source_version"],
        "frozen_manifest_sha256": selected["manifest_sha256"],
        "frozen_manifest_file_sha256": selected["manifest"]["sha256"],
        "current_frozen_source_mismatches": [],
        "runs": [row],
    }
    snapshot = {
        "run_id": row["run_id"],
        "level": "L1",
        "strictly_accepted": True,
        "acceptance": {
            "passed": True,
            "status": "passed",
            "checks": {
                "scenario_token_budget_policy": "passed",
                "scenario_model_usage_settled": "passed",
            },
        },
        "token_usage": {"input": 10, "output": 10},
    }
    return selected, report, {"current_source_runs": [snapshot]}


def test_core_fixture_has_all_current_declared_checks():
    assert audit.core_checks(valid_core()) == []


@pytest.mark.parametrize(
    "field", ["approved_assignment_valid", "admission_inventory_complete"]
)
def test_core_truthy_string_cannot_replace_true(field):
    row = valid_core()
    row["core_declared_source_audit"]["worker_inventories"][0][field] = "false"
    assert audit.core_checks(row)


@pytest.mark.parametrize("missing", ["worker_inventories", "tool_counters"])
def test_nonempty_core_sources_require_assignment_and_counter_inventory(missing):
    row = valid_core()
    row["core_declared_source_audit"][missing] = []
    assert audit.core_checks(row)


def test_pending_auditor_sentinel_cannot_authenticate_usage(tmp_path, monkeypatch):
    selected, report, _live = usage_fixture(tmp_path, monkeypatch)
    monkeypatch.setattr(audit, "CORE_AUDITOR_SHA256", "PENDING_CORE_AUDITOR_HASH")
    report["audit_script_sha256"] = audit.CORE_AUDITOR_SHA256
    result = audit.usage_extension(
        write_json(tmp_path / "audit.json", report), selected
    )
    assert result["passed"] is False


def test_failed_actual_model_compaction_cannot_pass_extension(tmp_path, monkeypatch):
    selected, report, _live = usage_fixture(tmp_path, monkeypatch)
    report["runs"][0]["model_compaction_checkpoints"] = {
        "applicable": True,
        "passed": False,
        "checkpoints": [],
        "errors": ["actual_model_compaction_checkpoints_required"],
    }
    result = audit.usage_extension(
        write_json(tmp_path / "audit.json", report), selected
    )
    assert result["passed"] is False


def test_legacy_capped_acceptance_cannot_masquerade_as_disabled_protocol(
    tmp_path, monkeypatch
):
    selected, report, live = usage_fixture(tmp_path, monkeypatch)
    live["current_source_runs"][0]["acceptance"]["checks"] = {
        "scenario_total_token_budget": "passed"
    }
    result = audit.live_usage_v29(
        write_json(tmp_path / "audit.json", report), selected, live
    )
    assert result["passed"] is False


def test_duplicate_usage_run_rows_cannot_pass_set_inventory(tmp_path, monkeypatch):
    selected, report, live = usage_fixture(tmp_path, monkeypatch)
    report["runs"].append(copy.deepcopy(report["runs"][0]))
    result = audit.live_usage_v29(
        write_json(tmp_path / "audit.json", report), selected, live
    )
    assert result["passed"] is False


@pytest.mark.parametrize("value", [-1, True, 1.5])
def test_invalid_known_usage_cannot_pass_artifact_reconciliation(
    tmp_path, monkeypatch, value
):
    selected, report, live = usage_fixture(tmp_path, monkeypatch)
    report["runs"][0]["known_gateway_tokens"] = value
    live["current_source_runs"][0]["token_usage"] = {"input": value, "output": 0}
    result = audit.live_usage_v29(
        write_json(tmp_path / "audit.json", report), selected, live
    )
    assert result["passed"] is False


def draft():
    return audit.read(Path(__file__).with_name("final-goals-v29-draft.json"))


def all_strict_flags_without_live_exchanges():
    required = {
        name
        for goal in draft()["goals"]
        for name in goal.get("required_strict_checks", [])
    }
    return {
        "all_three_levels_accepted": True,
        "current_source_runs": [
            {
                "run_id": "flags-only-" + level,
                "level": level,
                "strictly_accepted": True,
                "acceptance": {"checks": dict.fromkeys(required, "passed")},
            }
            for level in ("L1", "L2", "L3")
        ],
    }


@pytest.mark.parametrize("number", [12, 14])
def test_flags_alone_do_not_prove_model_compaction_or_process_restart(number):
    rows = audit.goals_from_draft(
        draft(),
        all_strict_flags_without_live_exchanges(),
        {"modes": {}},
        {"passed": False},
        "v29",
    )
    assert next(row for row in rows if row["number"] == number)[
        "acceptance_status"
    ] == ("not_demonstrated")


@pytest.mark.parametrize("number", [7, 9, 11, 13])
def test_supplement_or_memory_pass_does_not_erase_other_declared_requirements(number):
    supplemental = {
        "modes": {mode: {"passed": True} for mode in audit.SUPPLEMENT_MODES.values()}
    }
    rows = audit.goals_from_draft(
        draft(),
        {"all_three_levels_accepted": False, "current_source_runs": []},
        supplemental,
        {"passed": True},
        "v29",
    )
    assert next(row for row in rows if row["number"] == number)[
        "acceptance_status"
    ] == ("not_demonstrated")


@pytest.mark.parametrize("mode", ["parallel", "controlled-defect", "review-revision"])
def test_supplement_boolean_wrapper_has_no_actual_exchange_chain(
    tmp_path, monkeypatch, mode
):
    monkeypatch.setattr(audit, "REPO", tmp_path)
    selected = frozen()
    empty = write_json(tmp_path / "empty-proof.json", {})
    empty_ref = audit.evidence(empty)
    row = {
        **valid_core(),
        "mode": mode,
        "source_version": selected["source_version"],
        "frozen_manifest_sha256": selected["manifest_sha256"],
        "frozen_executable_sha256": selected["executable_snapshot_sha256"],
        "read_snapshot_total_changes": 0,
        "finished_driver_passed": True,
        "finished_driver_failures": [],
        "goal_audit": {
            "passed": True,
            "failures": [],
            "goal_evidence": {"passed": True},
            "usage": {"unknown_attempt_ids": []},
            "receipt_failures": [],
            "input_checks": [],
        },
    }
    for key in (
        "driver_record",
        "original_spec",
        "saved_evidence",
        "goal_auditor",
        "core_auditor",
        "reservation_samples",
    ):
        row[key] = empty_ref
    for key in (
        "original_spec_matches",
        "code_snapshots_match",
        "driver_snapshots_match",
        "saved_evidence_matches_recollection",
        "independent_passes_reconstructed",
        "known_settled_usage_and_other_limits",
        "fresh_workspace_no_opening_usage",
        "cumulative_token_budget_explicitly_disabled",
        "goal_exchange_bindings_valid",
    ):
        row[key] = True
    supplement_path = write_json(tmp_path / "supplement.json", row)
    index_path = write_json(
        tmp_path / "index.json",
        {"independent_audits": [audit.evidence(supplement_path)]},
    )
    result = audit.supplements(index_path, selected)
