                source
                for source in live["current_source_runs"]
                if source.get("strictly_accepted") is True
                and required
                <= {
                    name
                    for name, status in source.get("acceptance", {})
                    .get("checks", {})
                    .items()
                    if status == "passed"
                }
                and source.get("independent_continuity", {}).get(field) is True
                and source.get("model_compaction_checkpoints", {}).get("applicable")
                is True
                and source["model_compaction_checkpoints"].get("passed") is True
                and bool(source["model_compaction_checkpoints"].get("checkpoints"))
            ]
            accepted = strict and bool(qualifying)
            observation = {
                "qualifying_run_ids": [source["run_id"] for source in qualifying],
                "requirement": field,
            }
        else:
            accepted, observation = (
                strict,
                {
                    "all_three_strict_levels_accepted": live[
                        "all_three_levels_accepted"
                    ],
                    "required_checks_missing_from_accepted_runs": sorted(
                        required - observed_checks
                    ),
                },
            )
        row.update(
            source_version=source_version,
            acceptance_status="satisfied" if accepted else "not_demonstrated",
            independent_observation=observation,
        )
        goals.append(row)
    return goals


