    snapshot_ids = [row["run_id"] for row in live["current_source_runs"]]
    if len(run_ids) != len(set(run_ids)) or len(snapshot_ids) != len(set(snapshot_ids)):
        errors.append("duplicate_run_inventory")
    if (
        report.get("source_version") != frozen["source_version"]
        or report.get("frozen_manifest_sha256") != frozen["manifest_sha256"]
        or report.get("frozen_manifest_file_sha256") != frozen["manifest"]["sha256"]
        or report.get("current_frozen_source_mismatches")
    ):
        errors.append("usage_frozen_source_identity")
    for row in report.get("runs", []):
        run_id = row["run_id"]
        if (
            type(row.get("known_gateway_tokens")) is not int
            or row["known_gateway_tokens"] < 0
        ):
            errors.append("invalid_actual_usage:" + run_id)
        if not bound_reference(
            {
                "path": row["driver_record_path"],
                "bytes": (REPO / row["driver_record_path"]).stat().st_size,
                "sha256": row["driver_record_sha256"],
            }
        ):
            errors.append("driver_record_identity:" + run_id)
        for flag in (
            "accounting_checks_passed",
            "driver_usage_matches_database",
            "unknown_or_sent_reservations_never_refunded",
            "all_gateway_usage_known_and_settled",
