        ):
            errors.append("usage_assignment_or_snapshot:" + run_id)
        if (
            row.get("token_budgets_enforced") is not False
            or row.get("gateway_tokens_within_original_scenario_limit") is not None
        ):
            errors.append("explicit_disabled_token_protocol:" + run_id)
        if row.get("missing_gateway_usage_count") != 0:
            errors.append("unknown_model_attempt:" + run_id)
        if any(
            item.get("receipt_hash_matches") is not True
            for item in row.get("artifact_hash_checks", [])
        ) or any(
            item.get("original_live_evidence_valid") is not True
            for item in row.get("succeeded_node_live_evidence_revalidation", [])
        ):
            errors.append("current_artifact_and_node_proof:" + run_id)
        snapshot = snapshots.get(run_id)
        if snapshot is not None and (
            snapshot.get("acceptance", {})
            .get("checks", {})
            .get("scenario_token_budget_policy")
            != "passed"
            or "scenario_total_token_budget"
            in snapshot.get("acceptance", {}).get("checks", {})
            or any(
                type((snapshot.get("token_usage") or {}).get(key)) is not int
                or (snapshot.get("token_usage") or {})[key] < 0
                for key in ("input", "output")
            )
        ):
            errors.append("published_disabled_protocol_and_actual_usage:" + run_id)
        if (
            snapshot is None
            or row.get("acceptance_passed") != snapshot["acceptance"].get("passed")
            or sum(
                (snapshot.get("token_usage") or {}).get(key, 0)
                for key in ("input", "output")
            )
            != row["known_gateway_tokens"]
        ):
            errors.append("published_snapshot_binding:" + run_id)
        known += row["known_gateway_tokens"]
    if {row["run_id"] for row in report.get("runs", [])} != set(snapshots):
        errors.append("usage_run_inventory")
    return {
        "evidence": evidence(path),
        "runs": len(report.get("runs", [])),
        "known_tokens": known,
        "consistency_errors": errors,
        "passed": not errors,
        "token_budget_protocol": "disabled_by_user; no replacement cumulative cap; all usage must be known and settled",
    }


